/* ===== CORE: data model, content helpers, units, calendar math, calculator registry ===== */
const APP = { cats: [], chapters: [], byId: {}, calcs: {}, units: {}, idx: [], calcHome: {}, secById: {} };
const PI = Math.PI, D2R = PI / 180, R2D = 180 / PI;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const unesc = s => String(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');

/* ---- content helpers (return HTML strings) ---- */
const P = s => `<p>${s}</p>`;
const UL = a => `<ul>${a.map(x => `<li>${x}</li>`).join('')}</ul>`;
const OL = a => `<ol>${a.map(x => `<li>${x}</li>`).join('')}</ol>`;
const H = s => `<h4>${s}</h4>`;
const NOTE = s => `<div class="co note"><b>Note</b>${s}</div>`;
const WARN = s => `<div class="co warn"><b>Caution</b>${s}</div>`;
const DANGER = s => `<div class="co danger"><b>Danger / Safety</b>${s}</div>`;
const FX = (name, formula, note) => `<div class="fx"><b>${name}</b><code>${formula}</code>${note ? `<span>${note}</span>` : ''}</div>`;
const CALC = id => `<div class="slot calc-slot" data-calc="${id}"></div>`;
const CONV = cat => `<div class="slot conv-slot" data-conv="${cat}"></div>`;
const DYN = n => `<div class="slot dyn-slot" data-dyn="${n}"></div>`;
const GL = pairs => `<dl class="gl">${pairs.map(([t, d]) => `<dt data-idx="${t.replace(/"/g, '')}">${t}</dt><dd>${d}</dd>`).join('')}</dl>`;
/* T(head, rows, {cap, idx, filter}) – idx registers first column in the index; filter adds a live filter box */
const T = (head, rows, o = {}) => {
  const f = o.filter ? `<input class="tfilter" type="search" placeholder="Filter this table…" aria-label="Filter table">` : '';
  const th = head.map(h => `<th>${h}</th>`).join('');
  const dash = c => String(c).trim() === '' ? '—' : c;
  const tb = rows.map(r => `<tr>${r.map((c, i) => (i === 0 && o.idx) ? `<td data-idx="${String(c).replace(/<[^>]+>/g, '').replace(/"/g, '')}">${dash(c)}</td>` : `<td>${dash(c)}</td>`).join('')}</tr>`).join('');
  return `${f}<div class="tw"><table>${o.cap ? `<caption>${o.cap}</caption>` : ''}<thead><tr>${th}</tr></thead><tbody>${tb}</tbody></table></div>`;
};

/* ---- structure ---- */
function CAT(id, title, blurb, icon) { APP.cats.push({ id, title, blurb, icon, chapters: [] }); }
function S(id, title, blocks, o = {}) { return { id, title, html: blocks.join(''), kw: o.kw || [], see: o.see || [] }; }
function CH(id, cat, title, icon, intro, sections) {
  const c = { id, cat, title, icon, intro, sections };
  APP.chapters.push(c); APP.byId[id] = c;
  APP.cats.find(k => k.id === cat).chapters.push(c);
  sections.forEach(s => {
    s.ch = id; APP.secById[id + '--' + s.id] = s;
    (s.html.match(/data-calc="([^"]+)"/g) || []).forEach(m => { const k = m.slice(11, -1); if (!APP.calcHome[k]) APP.calcHome[k] = { ch: id, sec: s.id }; });
    (s.html.match(/data-idx="([^"]+)"/g) || []).forEach(m => APP.idx.push({ term: unesc(m.slice(10, -1)), ch: id, sec: s.id }));
    s.kw.forEach(k => APP.idx.push({ term: k, ch: id, sec: s.id }));
    APP.idx.push({ term: s.title, ch: id, sec: s.id });
  });
}
/* cross reference tokens: [[chapter#section|label]] or [[chapter|label]] */
function xr(html) {
  return html.replace(/\[\[([a-z0-9-]+)(?:#([a-z0-9-]+))?\|([^\]]+)\]\]/g, (m, c, s, l) =>
    `<a class="xref" href="#${c}${s ? '--' + s : ''}">${l}</a>`);
}

/* ---- number formatting ---- */
function fmt(n, sig = 6) {
  if (typeof n !== 'number') return String(n);
  if (!isFinite(n)) return '—';
  if (n === 0) return '0';
  const a = Math.abs(n);
  if (a >= 1e12 || a < 1e-4) return n.toExponential(sig - 1).replace(/\.?0+e/, 'e').replace('e+', '×10^').replace('e', '×10^');
  let s = Number(n.toPrecision(sig)).toString();
  if (s.includes('e')) return n.toExponential(sig - 1);
  const [i, d] = s.split('.');
  const ii = i.replace(/\B(?=(\d{3})+(?!\d))/g, (a >= 10000 ? ',' : ''));
  return d ? ii + '.' + d : ii;
}
const sig = (n, d = 2) => Number(n.toFixed(d));

/* ---- units ---- */
/* each unit: [symbol, name, factorToBase, 'aliases'] or [symbol,name,null,aliases,toBaseFn,fromBaseFn] */
function UC(key, label, base, defs) {
  APP.units[key] = {
    key, label, base, list: defs.map(d => ({
      s: d[0], n: d[1], f: d[2], a: (d[3] || '').split(' ').filter(Boolean), to: d[4] || (v => v * d[2]), fr: d[5] || (b => b / d[2])
    }))
  };
}
const normU = s => s.toLowerCase().replace(/[\s·.*^_\-]/g, '').replace(/²/g, '2').replace(/³/g, '3').replace(/[°]/g, '').replace(/µ/g, 'u');
function unitAliases(u) { return [u.s, u.n, ...u.a].map(normU); }
function convertUnit(cat, v, from, to) {
  const c = APP.units[cat], f = c.list.find(u => u.s === from), t = c.list.find(u => u.s === to);
  return t.fr(f.to(v));
}
function findUnits(text) {
  const k = normU(text), out = [];
  for (const c of Object.values(APP.units)) for (const u of c.list) if (unitAliases(u).includes(k)) out.push({ cat: c.key, u });
  return out;
}
function quickConvert(q) {
  q = q.replace(/^\s*(-?\d+)\s+(\d+)\/(\d+)/, (m, a, b, c) => String(+a + b / c)).replace(/^\s*(\d+)\/(\d+)/, (m, a, b) => String(a / b));
  const m = q.trim().match(/^(-?\d*\.?\d+(?:e[+-]?\d+)?)\s*(.+?)\s+(?:to|in|into|as|->|=|→)\s+(.+?)$/i);
  if (!m) return null;
  const v = parseFloat(m[1]), A = findUnits(m[2]), B = findUnits(m[3]);
  for (const a of A) for (const b of B) if (a.cat === b.cat) {
    return { v, cat: a.cat, from: a.u, to: b.u, out: convertUnit(a.cat, v, a.u.s, b.u.s), label: APP.units[a.cat].label };
  }
  return null;
}

