/* ---- calendar math (pure) ---- */
const CAL = {
  isLeap: y => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0,
  dim: (y, m) => [31, CAL.isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1],
  dow: (y, m, d) => { const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]; if (m < 3) y -= 1; return (y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) + t[m - 1] + d) % 7; }, /* 0 = Sunday */
  idx: y => CAL.dow(y, 1, 1) + 1 + (CAL.isLeap(y) ? 7 : 0), /* 1..14 */
  jdn: (y, m, d) => { const a = Math.floor((14 - m) / 12), yy = y + 4800 - a, mm = m + 12 * a - 3; return d + Math.floor((153 * mm + 2) / 5) + 365 * yy + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400) - 32045; },
  fromJdn: j => { const f = j + 1401 + Math.floor((Math.floor((4 * j + 274277) / 146097) * 3) / 4) - 38, e = 4 * f + 3, g = Math.floor((e % 1461) / 4), h = 5 * g + 2; const D = Math.floor((h % 153) / 5) + 1, M = ((Math.floor(h / 153) + 2) % 12) + 1, Y = Math.floor(e / 1461) - 4716 + Math.floor((12 + 2 - M) / 12); return { y: Y, m: M, d: D }; },
  doy: (y, m, d) => { let n = d; for (let i = 1; i < m; i++) n += CAL.dim(y, i); return n; },
  isoWeek: (y, m, d) => {
    const wd = (CAL.dow(y, m, d) + 6) % 7 + 1; let w = Math.floor((CAL.doy(y, m, d) - wd + 10) / 7), yr = y;
    const weeksIn = yy => { const p = (yy + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400)) % 7, q = yy - 1, p2 = (q + Math.floor(q / 4) - Math.floor(q / 100) + Math.floor(q / 400)) % 7; return (p === 4 || p2 === 3) ? 53 : 52; };
    if (w < 1) { yr = y - 1; w = weeksIn(yr); } else if (w > weeksIn(y)) { w = 1; yr = y + 1; }
    return { w, y: yr };
  },
  easter: y => { const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451), mo = Math.floor((h + l - 7 * m + 114) / 31), da = ((h + l - 7 * m + 114) % 31) + 1; return { y, m: mo, d: da }; },
  nth: (y, m, dw, n) => { const first = CAL.dow(y, m, 1); let d = 1 + ((dw - first + 7) % 7) + (n - 1) * 7; return d; },
  last: (y, m, dw) => { const dm = CAL.dim(y, m), ld = CAL.dow(y, m, dm); return dm - ((ld - dw + 7) % 7); },
  holidays: y => {
    const h = {}; const add = (m, d, n) => { h[m + '-' + d] = n; };
    add(1, 1, "New Year's Day"); add(1, CAL.nth(y, 1, 1, 3), 'Martin Luther King Jr. Day'); add(2, CAL.nth(y, 2, 1, 3), "Presidents' Day");
    add(5, CAL.last(y, 5, 1), 'Memorial Day'); if (y >= 2021) add(6, 19, 'Juneteenth'); add(7, 4, 'Independence Day'); add(9, CAL.nth(y, 9, 1, 1), 'Labor Day');
    add(10, CAL.nth(y, 10, 1, 2), 'Columbus / Indigenous Peoples Day'); add(11, 11, 'Veterans Day'); add(11, CAL.nth(y, 11, 4, 4), 'Thanksgiving'); add(12, 25, 'Christmas Day');
    const e = CAL.easter(y); add(e.m, e.d, 'Easter Sunday'); return h;
  }
};
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

/* ---- calculator registry ----
 calc({id,title,desc,cat,fields:[{k,l,d,u,s:[[v,label]..],opt,txt}],run(v)->rows|string, kw:[]})
 rows: [label,value,unit?] | 'Heading string'; return {err:'...'} for errors */
function calc(o) { o.cat = o.cat || ''; APP.calcs[o.id] = o; }
const F = (k, l, d, u, extra) => Object.assign({ k, l, d, u }, extra || {});
const SEL = (k, l, opts, d) => ({ k, l, s: opts, d: d !== undefined ? d : opts[0][0] });
/* ===== CATEGORIES ===== */
CAT('mech', 'Mechanical Engineering & Automotive', 'Machines, engines, hydraulics, fasteners, tools, rigging.', '⚙️');
CAT('constr', 'Construction & Building', 'Framing, structural metals, material weights, surveying and layout.', '🏗️');
CAT('elec', 'Electrical & Electronics', 'Wire, motors, circuits, components — with code and safety limits.', '⚡');
CAT('math', 'Mathematics & Scientific Principles', 'Algebra to trig, physics, chemistry, science and constants.', '📐');
CAT('mat', 'Materials & Industrial Processes', 'Aggregates, welding, adhesives, coatings and finishes.', '🧱');
CAT('fluid', 'Fluid Systems & Environmental Science', 'Gases, pipe, water, weather and weather safety.', '💧');
CAT('gen', 'General & Practical Reference', 'Terminology, geology, computers, first aid and money.', '📘');
CAT('ref', 'Reference Tables & Appendices', 'Conversions, 14-year perpetual calendar and the master index.', '📑');
CAT('music', 'Music Theory', 'Notes, rhythm, intervals, scales, chords, pitch and instrument tunings.', '🎼');
CAT('anaer', 'Anaerobic Exercise', 'Strength, power and interval training: loading, one-rep max, plates, sprints and safety.', '🏋️');
CAT('wild', 'Wild Edibles', 'Foraging safety, dangerous look-alikes, beginner edible plants, seasons and preparation.', '🌿');
CAT('cook', 'Cooking & Food Safety', 'Safe temperatures, storage, kitchen measures, substitutions, altitude and home preservation.', '🍳');
CAT('garden', 'Gardening & Soil', 'Soil and pH, fertilizer, planting data, hardiness zones, watering, compost and pests.', '🌱');
