/* ---- table builders and copy helpers ---- */
const kPrec = c => c.type === 'S' || c.type === 'D' || c.type === 'X' ? (c.type === 'D' ? 'Exact (value rounded to the digits shown)' : 'Exact (zero uncertainty)') : c.type === 'M' ? c.par + (c.ur ? '   (u_r = ' + c.ur.replace(/e-(\d+)/, ' × 10⁻$1').replace(/^(\d)/, '$1') + ')' : '') : c.type === 'R' ? 'Inherits the uncertainty of its inputs' + (c.ur ? ' (u_r ≈ ' + c.ur.replace(/e-(\d+)/, ' × 10⁻$1') + ')' : '') : c.type === 'T' ? 'Typical' + (c.par ? '; range ' + c.par : '; varies with sample and temperature') : 'Exact definition; digits shown are truncated';
const kTexUnit = u => u.replace(/[⁻⁰¹²³⁴⁵⁶⁷⁸⁹]+/g, m => '^{' + m.replace(/⁻/g, '-').replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g, d => '⁰¹²³⁴⁵⁶⁷⁸⁹'.indexOf(d)) + '}').replace(/·/g, '\\,').replace(/Ω/g, '\\Omega').replace(/µ/g, '\\mu ').replace(/\s+/g, '\\ ');
const kCopyText = (c, f) => {
  const unit = c.unit === '—' || c.unit === '(dimensionless)' ? '' : ' ' + c.unit, full = `${c.name} (${c.sym}) = ${c.n}${unit}  [${KTYPE[c.type][0]}; ${kPrec(c)}; ${c.src}]`;
  if (f === 'val') return c.n;
  if (f === 'valunit') return c.n + unit;
  if (f === 'sym') return `${c.sym} = ${c.n}${unit}`;
  if (f === 'py') return `${c.id.replace(/[^A-Za-z0-9_]/g, '_')} = ${c.n}${/^[-+]?\d+$/.test(c.n) ? '.0' : ''}  # ${c.unit}, ${KTYPE[c.type][0]}`;
  if (f === 'tex') { const m = c.n.match(/^(.*)e([-+]?\d+)$/); return (m ? `${m[1]} \\times 10^{${+m[2]}}` : c.n) + (unit ? '\\ \\mathrm{' + kTexUnit(c.unit) + '}' : ''); }
  if (f === 'json') return JSON.stringify({ name: c.name, symbol: c.sym, value: Number(c.n), value_text: c.n, unit: c.unit, type: KTYPE[c.type][0], precision: kPrec(c), source: c.src });
  return full;
};
const KHEAD = ['Constant', 'Symbol', 'Value', 'SI unit', 'Alternate units', 'Type', 'Precision', 'Definition', 'Source', 'Copy'];
const kRow = c => { const i = CONSTS.indexOf(c); return [c.name, kSym(c.sym), `<b class="kv">${kd(c.n)}</b><span class="kn" hidden>${c.n}</span>`, c.unit, c.alt || '—', `<span class="kt kt-${c.type}" title="${kEsc(KTYPE[c.type][1])}">${KTYPE[c.type][0]}</span>`, kPrec(c), c.def, c.src, `<button class="btn cp" data-ci="${i}" data-cf="val" title="Copy the value (machine format)">value</button> <button class="btn cp" data-ci="${i}" data-cf="valunit" title="Copy value and unit">+unit</button> <button class="btn cp" data-ci="${i}" data-cf="full" title="Copy the whole entry as text">entry</button>`]; };
