calc({ id: 'cst-unc', title: 'Standard uncertainty notation — 6.67430(15)e-11', desc: 'Expand CODATA parenthetical uncertainty into absolute and relative uncertainty and a range', kw: ['uncertainty', 'parenthetical uncertainty', 'relative uncertainty', 'CODATA notation', 'standard uncertainty', 'error bars', 'precision of a constant', 'ppm'], fields: [F('t', 'Value(uncertainty), optional exponent', '6.67430(15)e-11', '', { txt: 1 })],
  run: v => { const s = String(v.t).trim().replace(/\s/g, '').replace('×', 'x'), m = s.match(/^([+-]?\d+(?:\.\d+)?)\((\d+)\)(?:[eE]([+-]?\d+)|x10\^?([+-]?\d+))?$/); if (!m) return { err: 'Use the form 6.67430(15)e-11 or 1836.152673426(32).' }; const dec = (m[1].split('.')[1] || '').length, ex = +(m[3] || m[4] || 0), val = parseFloat(m[1]) * 10 ** ex, u = +m[2] * 10 ** (-dec) * 10 ** ex, rel = u / Math.abs(val), dig = Math.max(1, Math.floor(-Math.log10(rel))); return [['Value', val.toPrecision(m[1].replace(/[.+-]/g, '').replace(/^0+/, '').length)], ['Standard uncertainty', u.toPrecision(Math.max(2, m[2].length))], ['Relative standard uncertainty', rel], ['  in parts per million', rel * 1e6, 'ppm'], ['  in parts per billion', rel * 1e9, 'ppb'], ['About 68 % interval (±1σ)', (val - u).toPrecision(m[1].replace(/[.+-]/g, '').replace(/^0+/, '').length + 1) + ' to ' + (val + u).toPrecision(m[1].replace(/[.+-]/g, '').replace(/^0+/, '').length + 1)], ['About 95 % interval (±2σ)', (val - 2 * u).toPrecision(m[1].replace(/[.+-]/g, '').replace(/^0+/, '').length + 1) + ' to ' + (val + 2 * u).toPrecision(m[1].replace(/[.+-]/g, '').replace(/^0+/, '').length + 1)], ['Reliable significant digits', dig], 'The digits in parentheses are the standard uncertainty (1σ) in the last digits of the value.']; } });
