const CP_G = 9.80665, CP_SIGMA = 5.670374419e-8, CP_R = 8.314462618, CP_K = 8.9875517923e9, CP_E = 1.602176634e-19;
const CP_ORB = [[1, 0], [2, 0], [2, 1], [3, 0], [3, 1], [4, 0], [3, 2], [4, 1], [5, 0], [4, 2], [5, 1], [6, 0], [4, 3], [5, 2], [6, 1], [7, 0], [5, 3], [6, 2], [7, 1]];
const CP_LN = 'spdf', CP_NAME = o => o[0] + CP_LN[o[1]], CP_CAP = o => 2 * (2 * o[1] + 1);
const CP_EXC = { 24: { '4s': 1, '3d': 5 }, 29: { '4s': 1, '3d': 10 }, 41: { '5s': 1, '4d': 4 }, 42: { '5s': 1, '4d': 5 }, 44: { '5s': 1, '4d': 7 }, 45: { '5s': 1, '4d': 8 }, 46: { '5s': 0, '4d': 10 }, 47: { '5s': 1, '4d': 10 }, 57: { '4f': 0, '5d': 1 }, 58: { '4f': 1, '5d': 1 }, 64: { '4f': 7, '5d': 1 }, 78: { '6s': 1, '4f': 14, '5d': 9 }, 79: { '6s': 1, '4f': 14, '5d': 10 }, 89: { '5f': 0, '6d': 1 }, 90: { '5f': 0, '6d': 2 }, 91: { '5f': 2, '6d': 1 }, 92: { '5f': 3, '6d': 1 }, 93: { '5f': 4, '6d': 1 }, 96: { '5f': 7, '6d': 1 } };
const cpAufbau = e => { const occ = {}; let left = e; for (const o of CP_ORB) { if (left <= 0) break; const n = Math.min(left, CP_CAP(o)); occ[CP_NAME(o)] = n; left -= n; } return occ; };
const cpOcc = (z, charge) => { let occ; if (charge < 0) occ = cpAufbau(z - charge); else { occ = cpAufbau(z); if (CP_EXC[z]) Object.assign(occ, CP_EXC[z]); let rem = charge; const order = CP_ORB.filter(o => occ[CP_NAME(o)] > 0).sort((a, b) => b[0] - a[0] || b[1] - a[1]); for (const o of order) { while (rem > 0 && occ[CP_NAME(o)] > 0) { occ[CP_NAME(o)]--; rem--; } } } return occ; };
const cpShown = occ => CP_ORB.filter(o => occ[CP_NAME(o)] > 0).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
const cpSup = n => String(n).replace(/\d/g, d => '⁰¹²³⁴⁵⁶⁷⁸⁹'[d]);
const cpSub = s => s.replace(/(?<=[A-Za-z)\]])(\d+)/g, m => m.replace(/\d/g, d => '₀₁₂₃₄₅₆₇₈₉'[d]));
