    s += `<rect x="92" y="136" width="72" height="26" rx="12" fill="${MUT}" fill-opacity=".25" stroke="none"/><circle cx="126" cy="130" r="5" stroke="${ACC2}"/>` + lab(127, 204, 'Altostratus').replace('Altostratus', 'Altostrat.');
