calc({ id: 'cc-binop', title: 'Bitwise and binary arithmetic calculator', desc: 'AND, OR, XOR, NOT, shifts, rotate, add, subtract, multiply — with flags', kw: ['bitwise', 'AND OR XOR', 'bit shift', 'binary addition', 'carry flag', 'overflow', 'bit mask', 'rotate'], fields: [F('a', 'Value A (decimal, 0x hex, 0b binary)', '0xF0', '', { txt: 1 }), F('b', 'Value B (or shift count)', '0x3C', '', { txt: 1 }), SEL('op', 'Operation', [['and', 'A AND B'], ['or', 'A OR B'], ['xor', 'A XOR B'], ['nand', 'A NAND B'], ['nor', 'A NOR B'], ['xnor', 'A XNOR B'], ['not', 'NOT A'], ['shl', 'A << B (shift left)'], ['shr', 'A >> B (logical shift right)'], ['sar', 'A >> B (arithmetic shift right)'], ['rol', 'Rotate left by B'], ['ror', 'Rotate right by B'], ['add', 'A + B'], ['sub', 'A − B'], ['mul', 'A × B']]), SEL('w', 'Word size', [[8, '8-bit'], [16, '16-bit'], [32, '32-bit'], [64, '64-bit']], 8)],
  run: v => { try { const w = BigInt(v.w), mod = 1n << w, M = mod - 1n, half = mod >> 1n, fix = x => ((x % mod) + mod) % mod, A = fix(ccParse(v.a, 10)), B = fix(ccParse(v.b, 10)), sg = u => u >= half ? u - mod : u; let r, carry = null, ovf = null; const k = v.op, sh = Number(B % w); switch (k) { case 'and': r = A & B; break; case 'or': r = A | B; break; case 'xor': r = A ^ B; break; case 'nand': r = ~(A & B) & M; break; case 'nor': r = ~(A | B) & M; break; case 'xnor': r = ~(A ^ B) & M; break; case 'not': r = ~A & M; break; case 'shl': r = (A << B) & M; carry = B > 0n && B <= w ? Number((A >> (w - B)) & 1n) : 0; break; case 'shr': r = B >= w ? 0n : A >> B; break; case 'sar': r = fix(sg(A) >> (B >= w ? w - 1n : B)); break; case 'rol': r = ((A << BigInt(sh)) | (A >> (w - BigInt(sh)))) & M; break; case 'ror': r = ((A >> BigInt(sh)) | (A << (w - BigInt(sh)))) & M; break; case 'add': { const t = A + B; r = t & M; carry = t > M ? 1 : 0; ovf = (sg(A) >= 0n) === (sg(B) >= 0n) && (sg(r) >= 0n) !== (sg(A) >= 0n) ? 1 : 0; break; } case 'sub': { r = fix(A - B); carry = A < B ? 1 : 0; ovf = (sg(A) >= 0n) !== (sg(B) >= 0n) && (sg(r) >= 0n) !== (sg(A) >= 0n) ? 1 : 0; break; } default: { const t = A * B; r = t & M; carry = t > M ? 1 : 0; } } const out = [['A (' + v.w + '-bit)', ccGroup4(A.toString(2).padStart(v.w, '0')) + '  = ' + A], ['B (' + v.w + '-bit)', ccGroup4(B.toString(2).padStart(v.w, '0')) + '  = ' + B], ['Result (binary)', ccGroup4(r.toString(2).padStart(v.w, '0'))], ['Result (hex)', '0x' + r.toString(16).toUpperCase().padStart(v.w / 4, '0')], ['Result (unsigned)', r.toString()], ['Result (signed)', sg(r).toString()], ['Zero flag', r === 0n ? 1 : 0], ['Negative flag (MSB)', Number(r >> (w - 1n))]]; if (carry !== null) out.push([k === 'sub' ? 'Borrow (carry) flag' : 'Carry-out flag', carry]); if (ovf !== null) out.push(['Signed overflow flag', ovf]); out.push('Results wrap to the word size, as hardware does.'); return out; } catch (e) { return { err: e.message }; } } });

calc({ id: 'cc-float', title: 'IEEE 754 floating-point breakdown', desc: 'Decimal number, or a raw 0x bit pattern; 32-bit (single) or 64-bit (double)', kw: ['IEEE 754', 'floating point', 'float', 'double', 'mantissa', 'exponent', 'precision', '0.1', 'NaN', 'infinity'], fields: [F('n', 'Value (e.g. 0.1, -118.625, inf, or 0x40490FDB)', '-118.625', '', { txt: 1 }), SEL('w', 'Format', [[32, 'Single (float32)'], [64, 'Double (float64)']], 32)],
  run: v => { try { const dv = new DataView(new ArrayBuffer(8)), w = v.w, str = String(v.n).trim(); let bits; if (/^0x/i.test(str)) { bits = BigInt(str); if (bits >> BigInt(w)) return { err: 'Pattern longer than ' + w + ' bits.' }; } else { const x = /^[-+]?inf/i.test(str) ? (str[0] === '-' ? -Infinity : Infinity) : /^nan$/i.test(str) ? NaN : Number(str); if (Number.isNaN(x) && !/^nan$/i.test(str)) return { err: 'Not a number.' }; if (w === 32) { dv.setFloat32(0, x); bits = BigInt(dv.getUint32(0)); } else { dv.setFloat64(0, x); bits = dv.getBigUint64(0); } } const eb = w === 32 ? 8 : 11, mb = w === 32 ? 23 : 52, bs = bits.toString(2).padStart(w, '0'), sign = bs[0], eStr = bs.slice(1, 1 + eb), mStr = bs.slice(1 + eb), e = parseInt(eStr, 2), bias = (1 << (eb - 1)) - 1; if (w === 32) { dv.setUint32(0, Number(bits)); } else dv.setBigUint64(0, bits); const val = w === 32 ? dv.getFloat32(0) : dv.getFloat64(0); let cls; if (e === (1 << eb) - 1) cls = /^0*$/.test(mStr) ? 'Infinity' : 'NaN'; else if (e === 0) cls = /^0*$/.test(mStr) ? 'Zero' : 'Subnormal (denormal)'; else cls = 'Normal'; const out = [['Bit pattern', sign + ' ' + eStr + ' ' + mStr], ['Hex', '0x' + bits.toString(16).toUpperCase().padStart(w / 4, '0')], ['Sign bit', sign + (sign === '1' ? ' (negative)' : ' (positive)')], ['Exponent field (' + eb + ' bits)', e + ' (bias ' + bias + ')'], cls === 'Normal' ? ['Unbiased exponent', e - bias] : cls.startsWith('Sub') ? ['Unbiased exponent', 1 - bias] : '', ['Fraction field (' + mb + ' bits)', mStr], ['Class', cls], ['Stored value', Number.isFinite(val) ? val.toPrecision(w === 32 ? 9 : 17) : String(val)], ['Largest finite value', w === 32 ? '3.4028235 × 10³⁸' : '1.7976931 × 10³⁰⁸'], ['Decimal digits of precision', w === 32 ? '≈ 7' : '≈ 15–16']]; if (cls === 'Normal') out.push(['Value = ± 1.fraction × 2^exponent', (sign === '1' ? '−' : '+') + '1.' + mStr.replace(/0+$/, '') + ' × 2^' + (e - bias)]); return out.filter(Boolean); } catch (e) { return { err: e.message }; } } });

calc({ id: 'cc-bits', title: 'Bit tricks — population count, parity, byte order', desc: 'For a 32-bit value (decimal, 0x hex or 0b binary); optional second value for Hamming distance', kw: ['popcount', 'parity bit', 'endianness', 'byte swap', 'power of two', 'leading zeros', 'Hamming distance', 'bit reverse', 'little endian', 'big endian'], fields: [F('a', 'Value', '0x12345678', '', { txt: 1 }), F('b', 'Compare with (optional)', '0x12345679', '', { txt: 1 })],
  run: v => { try { const A = ccParse(v.a, 10), M = 0xFFFFFFFFn; if (A < 0n || A > M) return { err: 'Value must fit in 32 bits (0 to 4,294,967,295).' }; const bs = A.toString(2).padStart(32, '0'), pop = bs.split('1').length - 1, hex = A.toString(16).padStart(8, '0'), bytes = hex.match(/../g), out = [['Binary (32-bit)', ccGroup4(bs)], ['Hex', '0x' + hex.toUpperCase()], ['Population count (1 bits)', pop], ['Parity', pop % 2 ? 'odd number of 1s (even-parity bit = 1)' : 'even number of 1s (even-parity bit = 0)'], ['Leading zeros', A === 0n ? 32 : Math.clz32(Number(A))], ['Trailing zeros', A === 0n ? 32 : bs.length - 1 - bs.lastIndexOf('1')], ['Bit length', A === 0n ? 0 : 32 - Math.clz32(Number(A))], ['Power of two?', A > 0n && (A & (A - 1n)) === 0n ? 'yes' : 'no'], ['Next power of two ≥ value', A === 0n ? 1 : (1n << BigInt(A.toString(2).length - ((A & (A - 1n)) === 0n ? 1 : 0))).toString()], ['Bit-reversed (32-bit)', '0x' + BigInt('0b' + bs.split('').reverse().join('')).toString(16).toUpperCase().padStart(8, '0')], ['Big-endian bytes (network order)', bytes.join(' ').toUpperCase()], ['Little-endian bytes (x86, ARM)', bytes.slice().reverse().join(' ').toUpperCase()]]; if (String(v.b).trim()) { const B = ccParse(v.b, 10); if (B >= 0n && B <= M) { const x = (A ^ B).toString(2), hd = x.split('1').length - 1; out.push(['Hamming distance to the second value', hd], ['XOR of the two', '0x' + (A ^ B).toString(16).toUpperCase()]); } } return out; } catch (e) { return { err: e.message }; } } });

calc({ id: 'cc-text', title: 'Text ⇄ ASCII / Unicode / UTF-8 codes', desc: 'Show code points and UTF-8 bytes, or turn codes back into text', kw: ['ASCII', 'Unicode', 'UTF-8', 'character code', 'text to hex', 'hex to text', 'text to binary', 'code point', 'emoji bytes'], fields: [SEL('m', 'Direction', [['enc', 'Text → codes'], ['hex', 'Hex UTF-8 bytes → text'], ['dec', 'Decimal code points → text']]), F('t', 'Input', 'Hello, é € 😀', '', { txt: 1 })],
  run: v => { try { const s = String(v.t); if (v.m === 'enc') { const cps = [...s].map(c => c.codePointAt(0)), bytes = [...new TextEncoder().encode(s)], hx = n => n.toString(16).toUpperCase().padStart(2, '0'); return [['Characters (code points)', cps.length], ['Code points (decimal)', cps.slice(0, 64).join(' ')], ['Code points (Unicode)', cps.slice(0, 64).map(c => 'U+' + c.toString(16).toUpperCase().padStart(4, '0')).join(' ')], ['UTF-8 bytes (hex)', bytes.slice(0, 96).map(hx).join(' ')], ['UTF-8 bytes (decimal)', bytes.slice(0, 96).join(' ')], ['UTF-8 bytes (binary)', bytes.slice(0, 24).map(b => b.toString(2).padStart(8, '0')).join(' ') + (bytes.length > 24 ? ' …' : '')], ['Size in UTF-8', bytes.length, 'bytes'], ['Size in UTF-16', s.length * 2, 'bytes'], ['Size in UTF-32', cps.length * 4, 'bytes'], ['Pure ASCII?', cps.every(c => c < 128) ? 'yes (every character is 1 byte)' : 'no']]; } if (v.m === 'hex') { const hs = s.replace(/0x|[\s,]/gi, ''); if (!/^[0-9a-f]*$/i.test(hs) || hs.length % 2) return { err: 'Enter whole hex bytes such as 48 65 6C 6C 6F.' }; const arr = new Uint8Array(hs.match(/../g).map(h => parseInt(h, 16))); let txt; try { txt = new TextDecoder('utf-8', { fatal: true }).decode(arr); } catch (e) { return { err: 'Those bytes are not valid UTF-8.' }; } return [['Text', txt], ['Bytes', arr.length], ['Characters', [...txt].length]]; } const nums = s.split(/[\s,]+/).filter(Boolean).map(Number); if (!nums.length || nums.some(n => !Number.isInteger(n) || n < 0 || n > 0x10FFFF)) return { err: 'Enter decimal code points 0–1114111 separated by spaces.' }; return [['Text', String.fromCodePoint(...nums)], ['Characters', nums.length]]; } catch (e) { return { err: e.message }; } } });

const ccB64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
calc({ id: 'cc-base64', title: 'Base64 encoder / decoder', desc: 'Text is converted to UTF-8 bytes first; standard alphabet with = padding', kw: ['base64', 'encode', 'decode', 'binary to text', 'data URI', 'MIME'], fields: [SEL('m', 'Direction', [['e', 'Text → Base64'], ['d', 'Base64 → text']]), F('t', 'Input', 'Hello, World!', '', { txt: 1 })],
  run: v => { try { const s = String(v.t); if (v.m === 'e') { const b = new TextEncoder().encode(s); let o = ''; for (let i = 0; i < b.length; i += 3) { const n = (b[i] << 16) | ((b[i + 1] || 0) << 8) | (b[i + 2] || 0); o += ccB64[n >> 18] + ccB64[(n >> 12) & 63] + (i + 1 < b.length ? ccB64[(n >> 6) & 63] : '=') + (i + 2 < b.length ? ccB64[n & 63] : '='); } return [['Base64', o], ['Input bytes', b.length], ['Output characters', o.length], ['Size increase', b.length ? (o.length / b.length - 1) * 100 : 0, '%'], 'Every 3 bytes become 4 characters (+33%); = pads the last group.']; } const c = s.replace(/\s/g, '').replace(/-/g, '+').replace(/_/g, '/').replace(/=+$/, ''); if (/[^A-Za-z0-9+/]/.test(c) || c.length % 4 === 1) return { err: 'Not valid Base64.' }; const b = []; for (let i = 0; i < c.length; i += 4) { const g = [...c.slice(i, i + 4)].map(ch => ccB64.indexOf(ch)), n = (g[0] << 18) | (g[1] << 12) | ((g[2] || 0) << 6) | (g[3] || 0); b.push((n >> 16) & 255); if (g.length > 2) b.push((n >> 8) & 255); if (g.length > 3) b.push(n & 255); } let t; try { t = new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(b)); } catch (e) { return { err: 'Decoded bytes are not valid UTF-8 text.' }; } return [['Text', t], ['Bytes', b.length], ['Hex', b.slice(0, 48).map(x => x.toString(16).toUpperCase().padStart(2, '0')).join(' ')]]; } catch (e) { return { err: e.message }; } } });

calc({ id: 'cc-hash', title: 'Checksums — CRC-32, Adler-32, FNV-1a, 8-bit sum', desc: 'Error-detection codes of the text (UTF-8 bytes). Not cryptographic hashes.', kw: ['CRC32', 'checksum', 'Adler-32', 'FNV', 'hash', 'error detection', 'parity', 'integrity'], fields: [F('t', 'Text', 'The quick brown fox jumps over the lazy dog', '', { txt: 1 })],
  run: v => { const b = new TextEncoder().encode(String(v.t)); let c = 0xFFFFFFFF; for (const x of b) { c ^= x; for (let k = 0; k < 8; k++) c = (c >>> 1) ^ (0xEDB88320 & -(c & 1)); } c = (c ^ 0xFFFFFFFF) >>> 0; let a = 1, d = 0; for (const x of b) { a = (a + x) % 65521; d = (d + a) % 65521; } const ad = ((d << 16) | a) >>> 0; let f = 0x811C9DC5; for (const x of b) { f ^= x; f = Math.imul(f, 0x01000193) >>> 0; } const s8 = b.reduce((p, x) => (p + x) & 255, 0), x8 = b.reduce((p, x) => p ^ x, 0), h = (n, w) => '0x' + n.toString(16).toUpperCase().padStart(w, '0'); return [['Bytes', b.length], ['CRC-32 (IEEE, used by ZIP, PNG, Ethernet)', h(c, 8)], ['Adler-32 (zlib)', h(ad, 8)], ['FNV-1a 32-bit', h(f, 8)], ['8-bit sum', h(s8, 2)], ['8-bit XOR', h(x8, 2)], 'Checksums detect accidental errors only; use SHA-256 or stronger for security. CRC-32 of "The quick brown fox jumps over the lazy dog" is 0x414FA339.']; } });

calc({ id: 'cc-color', title: 'Hex color ⇄ RGB, HSL and contrast', desc: 'Enter #RRGGBB or #RGB', kw: ['hex color', 'RGB', 'HSL', 'color code', 'web colors', 'contrast ratio', 'WCAG', '24-bit color'], fields: [F('h', 'Hex color', '#FF8800', '', { txt: 1 })],
  run: v => { let s = String(v.h).trim().replace(/^#/, ''); if (/^[0-9a-f]{3}$/i.test(s)) s = s.split('').map(c => c + c).join(''); if (!/^[0-9a-f]{6}$/i.test(s)) return { err: 'Use 3 or 6 hex digits, for example #F80 or #FF8800.' }; const r = parseInt(s.slice(0, 2), 16), g = parseInt(s.slice(2, 4), 16), b = parseInt(s.slice(4), 16), mx = Math.max(r, g, b) / 255, mn = Math.min(r, g, b) / 255, l = (mx + mn) / 2, d = mx - mn; let hh = 0; if (d) { if (mx === r / 255) hh = ((g - b) / 255 / d) % 6; else if (mx === g / 255) hh = (b - r) / 255 / d + 2; else hh = (r - g) / 255 / d + 4; hh *= 60; if (hh < 0) hh += 360; } const sat = d ? d / (1 - Math.abs(2 * l - 1)) : 0, lin = c => { c /= 255; return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); }, L = 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b); return [['Hex', '#' + s.toUpperCase()], ['Red / Green / Blue', r + ' / ' + g + ' / ' + b], ['CSS', 'rgb(' + r + ', ' + g + ', ' + b + ')'], ['Percent', Math.round(r / 2.55) + '% / ' + Math.round(g / 2.55) + '% / ' + Math.round(b / 2.55) + '%'], ['24-bit integer', (r * 65536 + g * 256 + b)], ['Binary', ccGroup4([r, g, b].map(x => x.toString(2).padStart(8, '0')).join(''))], ['HSL', 'hsl(' + Math.round(hh) + ', ' + Math.round(sat * 100) + '%, ' + Math.round(l * 100) + '%)'], ['Relative luminance', L], ['Contrast vs white', (1.05) / (L + 0.05)], ['Contrast vs black', (L + 0.05) / 0.05], 'WCAG asks for at least 4.5 : 1 for normal text and 3 : 1 for large text.']; } });

calc({ id: 'cc-ipconv', title: 'IPv4 address ⇄ decimal, hex and binary', desc: 'Dotted address, a 32-bit decimal number or 0x hex', kw: ['IP address', 'IPv4', 'dotted decimal', 'IP to integer', 'IP to hex', 'IP to binary', 'private address'], fields: [F('ip', 'Address or 32-bit number', '192.168.1.130', '', { txt: 1 })],
  run: v => { try { const s = String(v.ip).trim(); let n; const m = s.match(/^(\d+)\.(\d+)\.(\d+)\.(\d+)$/); if (m) { if (m.slice(1).some(x => +x > 255)) return { err: 'Each part must be 0–255.' }; n = m.slice(1).reduce((p, c) => p * 256n + BigInt(c), 0n); } else { n = ccParse(s, 10); if (n < 0n || n > 0xFFFFFFFFn) return { err: 'Must be 0 to 4,294,967,295.' }; } const o = [Number(n >> 24n), Number((n >> 16n) & 255n), Number((n >> 8n) & 255n), Number(n & 255n)], dd = o.join('.'), t = o[0] === 10 || (o[0] === 172 && o[1] >= 16 && o[1] <= 31) || (o[0] === 192 && o[1] === 168) ? 'Private (RFC 1918)' : o[0] === 127 ? 'Loopback' : o[0] === 169 && o[1] === 254 ? 'Link-local' : o[0] >= 224 && o[0] <= 239 ? 'Multicast' : o[0] >= 240 ? 'Reserved' : o[0] === 0 ? 'This network' : o[0] === 100 && o[1] >= 64 && o[1] <= 127 ? 'Carrier-grade NAT' : 'Public (routable)'; return [['Dotted decimal', dd], ['32-bit decimal', n.toString()], ['Hexadecimal', '0x' + n.toString(16).toUpperCase().padStart(8, '0')], ['Binary', o.map(x => x.toString(2).padStart(8, '0')).join('.')], ['Octets (hex)', o.map(x => x.toString(16).toUpperCase().padStart(2, '0')).join('.')], ['Type', t], ['Legacy class', o[0] < 128 ? 'A' : o[0] < 192 ? 'B' : o[0] < 224 ? 'C' : o[0] < 240 ? 'D (multicast)' : 'E']]; } catch (e) { return { err: e.message }; } } });

calc({ id: 'cc-addr', title: 'Address space — address bits ⇄ memory size', desc: 'Give address bits OR a size in bytes (leave the other blank)', free: true, kw: ['address bus', '32-bit', '64-bit', 'addressable memory', 'address bits', '4 GiB limit', 'memory size'], fields: [F('n', 'Address bits', 32, 'bits', { opt: 1 }), F('b', 'Memory size', '', 'bytes', { opt: 1 })],
  run: v => { if ((v.n === null) === (v.b === null)) return 'Fill either address bits or a size in bytes.'; if (v.n !== null) { if (!(v.n >= 1 && v.n <= 128)) return { err: 'Use 1–128 bits.' }; const N = 2n ** BigInt(Math.round(v.n)); return [['Distinct addresses', ccComma(N)], ['Addressable bytes (byte-addressed)', ccHuman(N, true)], ['In decimal units', ccHuman(N, false)], ['Highest address (hex)', '0x' + (N - 1n).toString(16).toUpperCase()], v.n === 32 ? '32-bit systems can address 4 GiB.' : v.n === 64 ? 'Current 64-bit CPUs implement 48 to 57 address bits (256 TiB to 128 PiB).' : '']; } if (!(v.b >= 1)) return { err: 'Size must be at least 1 byte.' }; const bits = Math.ceil(Math.log2(v.b)); return [['Address bits needed', bits], ['Addresses available', ccComma(2n ** BigInt(bits))], ['Size (binary units)', ccHuman(v.b, true)], ['Size (decimal units)', ccHuman(v.b, false)]]; } });

calc({ id: 'cc-cpu', title: 'Processor speed — clock, cycle time, IPC and FLOPS', desc: 'Peak throughput estimates', kw: ['clock speed', 'GHz', 'cycle time', 'IPC', 'cores', 'FLOPS', 'instructions per second', 'CPU performance'], fields: [F('f', 'Clock frequency', 4.2, 'GHz'), F('c', 'Cores', 8), F('i', 'Instructions per cycle per core (IPC)', 3), F('fl', 'FLOPs per cycle per core (SIMD × FMA)', 16), F('n', 'Instructions in the program', 1e9)],
  run: v => { const f = v.f * 1e9, ips = f * v.i * v.c; return [['Cycle time', 1 / f * 1e9, 'ns'], ['Distance light travels per cycle', 299792458 / f * 100, 'cm'], ['Instructions/s per core', f * v.i / 1e9, 'GIPS'], ['Instructions/s, all cores (peak)', ips / 1e9, 'GIPS'], ['Peak floating-point', f * v.fl * v.c / 1e9, 'GFLOPS'], ['Time for the program on one core', ccDur(v.n / (f * v.i))], ['Time on all cores (perfect scaling)', ccDur(v.n / ips)], 'Real programs rarely reach peak: memory stalls, branches and serial code limit speed (Amdahl\'s law).']; } });

calc({ id: 'cc-membw', title: 'Memory bandwidth (DDR transfer rates)', desc: 'Peak = transfers/s × bus width ÷ 8 × channels', kw: ['memory bandwidth', 'DDR4', 'DDR5', 'MT/s', 'memory speed', 'channels', 'GB/s'], fields: [SEL('r', 'Memory type', [[1600, 'DDR3-1600 (1600 MT/s)'], [2400, 'DDR4-2400'], [3200, 'DDR4-3200'], [4800, 'DDR5-4800'], [5600, 'DDR5-5600'], [6000, 'DDR5-6000'], [6400, 'DDR5-6400 / LPDDR5-6400']], 3200), F('rc', 'Custom MT/s (0 = use choice)', 0, 'MT/s', { opt: 1 }), F('w', 'Bus width per channel', 64, 'bit'), F('c', 'Channels', 2)],
  run: v => { const r = v.rc ? v.rc : v.r, bw = r * 1e6 * v.w / 8 * v.c; return [['Transfer rate', r, 'MT/s'], ['Real clock (DDR = 2 transfers/clock)', r / 2, 'MHz'], ['Peak bandwidth', bw / 1e9, 'GB/s'], ['Peak bandwidth', bw / 1073741824, 'GiB/s'], ['Peak bandwidth', bw * 8 / 1e9, 'Gbit/s'], ['Time to read 16 GB once', 16e9 / bw * 1000, 'ms'], 'Peak is a ceiling; sustained speed is typically 70–90% of it. The name "3200" in DDR4-3200 is MT/s, not MB/s (PC4-25600 = 25.6 GB/s).']; } });

calc({ id: 'cc-drive', title: 'Drive capacity — advertised vs what the OS shows', desc: 'Manufacturers use decimal units (1 TB = 10¹² bytes); many operating systems show binary units', kw: ['hard drive capacity', 'advertised capacity', 'missing space', '1TB shows 931GB', 'GiB', 'formatted capacity', 'how many files'], fields: [F('c', 'Advertised capacity', 1, ''), SEL('u', 'Unit', [[1e6, 'MB'], [1e9, 'GB'], [1e12, 'TB'], [1e15, 'PB']], 1e12), F('o', 'File-system overhead', 1, '%'), F('s', 'Average file size', 5, 'MB')],
  run: v => { const B = v.c * v.u, usable = B * (1 - v.o / 100); return [['Capacity in bytes', B, 'B'], ['In binary units', B / 1073741824, 'GiB'], ['In binary units', B / 1099511627776, 'TiB'], ['Difference vs the label', (1 - B / (B / 1073741824 * 1e9)) * 100, '%'], ['Usable after overhead', usable / 1073741824, 'GiB'], ['Usable after overhead', usable / 1e9, 'GB'], ['Files that fit', Math.floor(usable / (v.s * 1e6)), 'files'], 'Windows labels binary units as "GB"; macOS and most Linux tools use decimal GB, so a 1 TB drive shows 1 TB there and about 931 GB (really GiB) in Windows.']; } });

calc({ id: 'cc-raid', title: 'RAID capacity and fault tolerance', desc: 'Usable space from N identical drives', kw: ['RAID', 'RAID 5', 'RAID 1', 'RAID 10', 'RAID 6', 'usable capacity', 'parity', 'mirror'], fields: [SEL('l', 'RAID level', [['0', 'RAID 0 (striping)'], ['1', 'RAID 1 (mirror)'], ['5', 'RAID 5 (single parity)'], ['6', 'RAID 6 (double parity)'], ['10', 'RAID 10 (mirrored stripes)']], '5'), F('n', 'Number of drives', 4), F('s', 'Size of each drive', 4, 'TB')],
  run: v => { const n = Math.round(v.n), l = v.l, mn = { '0': 2, '1': 2, '5': 3, '6': 4, '10': 4 }[l]; if (n < mn) return { err: 'RAID ' + l + ' needs at least ' + mn + ' drives.' }; if (l === '10' && n % 2) return { err: 'RAID 10 needs an even number of drives.' }; const usable = { '0': n, '1': 1, '5': n - 1, '6': n - 2, '10': n / 2 }[l] * v.s, tol = { '0': '0 drives (any failure loses everything)', '1': (n - 1) + ' drives', '5': '1 drive', '6': '2 drives', '10': '1 drive guaranteed (up to one per mirror pair)' }[l]; return [['Raw capacity', n * v.s, 'TB'], ['Usable capacity', usable, 'TB'], ['Efficiency', usable / (n * v.s) * 100, '%'], ['Drive failures survived', tol], 'RAID is not a backup: it does not protect against deletion, corruption, ransomware or fire. Keep separate backups (3-2-1).']; } });

calc({ id: 'cc-xfer-time', title: 'Transfer time and required bandwidth', desc: 'File size ÷ effective link speed, or the speed needed to finish by a deadline', kw: ['download time', 'upload time', 'transfer time', 'file size', 'bandwidth needed', 'Mbps', 'backup time', 'network speed'], fields: [F('s', 'Data size', 4.7, ''), SEL('su', 'Size unit', [[1e3, 'kB'], [1e6, 'MB'], [1e9, 'GB'], [1e12, 'TB'], [1024, 'KiB'], [1048576, 'MiB'], [1073741824, 'GiB'], [1099511627776, 'TiB']], 1e9), F('r', 'Link speed', 100, ''), SEL('ru', 'Speed unit', [[1e3, 'kbit/s'], [1e6, 'Mbit/s'], [1e9, 'Gbit/s'], [8e6, 'MB/s'], [8e9, 'GB/s']], 1e6), F('e', 'Efficiency (protocol overhead, sharing)', 90, '%'), F('t', 'Deadline (optional)', 0, 'min', { opt: 1 })],
  run: v => { const bits = v.s * v.su * 8, rate = v.r * v.ru * v.e / 100, t = bits / rate, out = [['Effective throughput', rate / 1e6, 'Mbit/s'], ['Effective throughput', rate / 8e6, 'MB/s'], ['Transfer time', ccDur(t)], ['Transfer time', t, 's'], ['Data volume', ccHuman(v.s * v.su, false) + '  (' + ccHuman(v.s * v.su, true) + ')']]; if (v.t) { const need = bits / (v.t * 60) / (v.e / 100); out.push(['Link speed needed for the deadline', need / 1e6, 'Mbit/s'], ['…in bytes per second', need / 8e6, 'MB/s']); } out.push('Typical efficiency is 85–95% on Ethernet and 50–70% on Wi-Fi; speeds quoted by providers are in bits per second.'); return out; } });

calc({ id: 'cc-audio', title: 'Digital audio size and bitrate (uncompressed PCM)', desc: 'Sample rate × bit depth × channels', kw: ['audio file size', 'sample rate', 'bit depth', 'PCM', 'WAV', 'CD quality', '44.1 kHz', 'bitrate'], fields: [F('fs', 'Sample rate', 44.1, 'kHz'), F('bd', 'Bit depth', 16, 'bits'), F('ch', 'Channels', 2), F('t', 'Duration', 3.5, 'min')],
  run: v => { const bps = v.fs * 1000 * v.bd * v.ch, bytes = bps / 8 * v.t * 60; return [['Data rate', bps / 1000, 'kbit/s'], ['Data rate', bps / 8 / 1000, 'kB/s'], ['File size', bytes / 1e6, 'MB'], ['File size', bytes / 1048576, 'MiB'], ['Per hour', bps / 8 * 3600 / 1e9, 'GB'], ['Highest frequency (Nyquist)', v.fs / 2, 'kHz'], ['Dynamic range (≈ 6.02 dB/bit)', 6.02 * v.bd + 1.76, 'dB'], 'CD audio (44.1 kHz, 16-bit, stereo) is 1,411.2 kbit/s; MP3/AAC at 128–256 kbit/s is about 5–11 times smaller.']; } });

calc({ id: 'cc-image', title: 'Image and raw video size', desc: 'Width × height × bits per pixel (× frames)', kw: ['image size', 'resolution', 'megapixels', 'bit depth', 'raw video', 'uncompressed', 'frame rate', '4K'], fields: [F('w', 'Width', 1920, 'px'), F('h', 'Height', 1080, 'px'), F('bpp', 'Bits per pixel (24 = RGB, 32 = RGBA)', 24, 'bits'), F('f', 'Frames (1 = still image)', 1), F('fps', 'Frame rate (for video)', 30, 'fps')],
  run: v => { if (!(v.h > 0) || !(v.w > 0)) return { err: 'Width and height must be above zero.' }; const px = v.w * v.h, frame = px * v.bpp / 8, total = frame * v.f; return [['Pixels', px], ['Megapixels', px / 1e6, 'MP'], ['Colors per pixel (2^bits)', v.bpp <= 32 ? Math.pow(2, v.bpp) : '2^' + v.bpp], ['Size of one frame', frame / 1e6, 'MB'], ['Total size', total / 1e6, 'MB'], ['Total size', total / 1048576, 'MiB'], ['Video data rate at the frame rate', frame * v.fps * 8 / 1e6, 'Mbit/s'], ['Aspect ratio', (v.w / v.h).toFixed(3) + ' : 1'], 'Real files are compressed: JPEG 5–20×, H.264/H.265 video 100–500×.']; } });

calc({ id: 'cc-logic', title: 'Boolean expression — truth table and minimization', desc: 'Variables A–E; operators AND OR NOT XOR NAND NOR XNOR, & | ! ^ + · ′ (prime), parentheses, implied AND (AB)', kw: ['truth table', 'Boolean algebra', 'logic gates', 'simplify Boolean', 'Karnaugh map', 'minterm', 'sum of products', 'Quine-McCluskey', 'De Morgan', 'logic expression'], fields: [F('e', 'Expression', "A'B + AB' + AB", '', { txt: 1 })],
  run: v => { try { const src = String(v.e).trim(); if (!src) return { err: 'Enter an expression.' }; const toks = []; const re = /([A-Za-z]+)|([01])|(\()|(\))|([&·*∧])|([|+∨])|([\^⊕])|([!~¬'′])/g; let m, last = 0; while ((m = re.exec(src)) !== null) { if (/\S/.test(src.slice(last, m.index))) throw new Error('Unexpected "' + src.slice(last, m.index).trim() + '"'); last = re.lastIndex; if (m[1]) { const w = m[1].toUpperCase(); if (['AND', 'OR', 'NOT', 'XOR', 'NAND', 'NOR', 'XNOR'].includes(w)) toks.push({ t: w }); else for (const ch of w) toks.push({ t: 'V', v: ch }); } else if (m[2]) toks.push({ t: 'C', v: +m[2] }); else if (m[3]) toks.push({ t: '(' }); else if (m[4]) toks.push({ t: ')' }); else if (m[5]) toks.push({ t: 'AND' }); else if (m[6]) toks.push({ t: 'OR' }); else if (m[7]) toks.push({ t: 'XOR' }); else toks.push({ t: m[8] === "'" || m[8] === '′' ? 'PRIME' : 'NOT' }); } if (/\S/.test(src.slice(last))) throw new Error('Unexpected "' + src.slice(last).trim() + '"'); const vars = [...new Set(toks.filter(x => x.t === 'V').map(x => x.v))].sort(); if (vars.length > 5) return { err: 'Use at most 5 variables.' }; let p = 0; const peek = () => toks[p] && toks[p].t, eat = () => toks[p++]; const startsFactor = () => ['V', 'C', '(', 'NOT'].includes(peek()); const prim = () => { const x = eat(); if (!x) throw new Error('Expression ended unexpectedly'); let node; if (x.t === 'V') node = e => e[x.v]; else if (x.t === 'C') node = () => x.v; else if (x.t === '(') { node = pOr(); if (peek() !== ')') throw new Error('Missing )'); eat(); } else throw new Error('Unexpected ' + x.t); while (peek() === 'PRIME') { eat(); const n0 = node; node = e => 1 - n0(e); } return node; }, un = () => { if (peek() === 'NOT') { eat(); const a = un(); return e => 1 - a(e); } return prim(); }, pAnd = () => { let a = un(); while (peek() === 'AND' || peek() === 'NAND' || startsFactor()) { const op = peek() === 'AND' || peek() === 'NAND' ? eat().t : 'AND', b = un(), a0 = a; a = op === 'AND' ? e => a0(e) & b(e) : e => 1 - (a0(e) & b(e)); } return a; }, pXor = () => { let a = pAnd(); while (peek() === 'XOR' || peek() === 'XNOR') { const op = eat().t, b = pAnd(), a0 = a; a = op === 'XOR' ? e => a0(e) ^ b(e) : e => 1 - (a0(e) ^ b(e)); } return a; }, pOr = () => { let a = pXor(); while (peek() === 'OR' || peek() === 'NOR') { const op = eat().t, b = pXor(), a0 = a; a = op === 'OR' ? e => a0(e) | b(e) : e => 1 - (a0(e) | b(e)); } return a; }; const f = pOr(); if (p < toks.length) throw new Error('Unexpected ' + toks[p].t); const n = vars.length, rows = 1 << n, mins = []; const out = [['Variables', vars.join(', ') || '(none)']]; for (let r = 0; r < rows; r++) { const e = {}; vars.forEach((x, i) => e[x] = (r >> (n - 1 - i)) & 1); const y = f(e); if (y) mins.push(r); out.push([vars.map(x => x + '=' + e[x]).join(' ') || 'constant', 'F = ' + y]); } out.push(['Minterms Σm', mins.length ? mins.join(', ') : 'none'], ['Maxterms ΠM', [...Array(rows).keys()].filter(r => !mins.includes(r)).join(', ') || 'none'], ['Rows that are true', mins.length + ' of ' + rows]); if (mins.length === 0) out.push(['Type', 'Contradiction (always 0)'], ['Simplified', '0']); else if (mins.length === rows) out.push(['Type', 'Tautology (always 1)'], ['Simplified', '1']); else { const fmt = s => s.split('').map((c, i) => c === '-' ? '' : vars[i] + (c === '0' ? "'" : '')).join(''); let cur = mins.map(m => m.toString(2).padStart(n, '0')), primes = []; while (cur.length) { const used = new Set(), nxt = new Set(); for (let i = 0; i < cur.length; i++) for (let j = i + 1; j < cur.length; j++) { let d = -1, ok = true; for (let k = 0; k < n; k++) if (cur[i][k] !== cur[j][k]) { if (d >= 0 || cur[i][k] === '-' || cur[j][k] === '-') { ok = false; break; } d = k; } if (ok && d >= 0) { used.add(cur[i]); used.add(cur[j]); nxt.add(cur[i].slice(0, d) + '-' + cur[i].slice(d + 1)); } } primes.push(...cur.filter(x => !used.has(x))); cur = [...nxt]; } primes = [...new Set(primes)]; const covers = (pr, m) => pr.split('').every((c, i) => c === '-' || c === ((m >> (n - 1 - i)) & 1).toString()); let left = new Set(mins), chosen = []; for (const m of mins) { const cs = primes.filter(pr => covers(pr, m)); if (cs.length === 1 && !chosen.includes(cs[0])) { chosen.push(cs[0]); } } chosen.forEach(pr => mins.forEach(m => { if (covers(pr, m)) left.delete(m); })); while (left.size) { let best = null, bc = -1; for (const pr of primes) { const c = [...left].filter(m => covers(pr, m)).length; if (c > bc) { bc = c; best = pr; } } chosen.push(best); [...left].forEach(m => { if (covers(best, m)) left.delete(m); }); } out.push(['Minimal sum of products', chosen.map(fmt).map(t => t || '1').join(' + ')], ['Canonical SOP (minterms)', mins.map(m => '(' + m.toString(2).padStart(n, '0').split('').map((c, i) => vars[i] + (c === '0' ? "'" : '')).join('') + ')').join(' + ')], ['Prime implicants', primes.map(fmt).join(',  ')]); } out.push("Precedence: NOT, then AND/NAND, then XOR/XNOR, then OR/NOR. A' or !A or NOT A means NOT A."); return out; } catch (e) { return { err: e.message }; } } });

calc({ id: 'cc-serial', title: 'Serial (UART) throughput', desc: 'Baud rate, frame format and effective data rate', kw: ['UART', 'baud rate', 'serial port', 'RS-232', '9600 baud', 'start bit', 'stop bit', 'parity', 'bytes per second'], fields: [SEL('b', 'Baud rate', [[300, '300'], [1200, '1,200'], [2400, '2,400'], [9600, '9,600'], [19200, '19,200'], [38400, '38,400'], [57600, '57,600'], [115200, '115,200'], [230400, '230,400'], [921600, '921,600']], 9600), SEL('d', 'Data bits', [[5, '5'], [6, '6'], [7, '7'], [8, '8'], [9, '9']], 8), SEL('p', 'Parity bit', [[0, 'None'], [1, 'Even / odd / mark / space']], 0), SEL('s', 'Stop bits', [[1, '1'], [1.5, '1.5'], [2, '2']], 1), F('n', 'Bytes to send', 1024)],
  run: v => { const fr = 1 + v.d + v.p + v.s, bytes = v.b / fr; return [['Bits per frame (start + data + parity + stop)', fr], ['Frames (characters) per second', bytes], ['Useful data rate', bytes * v.d, 'bit/s'], ['Efficiency', v.d / fr * 100, '%'], ['Time per character', fr / v.b * 1000, 'ms'], ['Time to send the bytes', ccDur(v.n * fr / v.b)], '8N1 (8 data bits, no parity, 1 stop bit) uses 10 bit-times per byte, so 9,600 baud ≈ 960 bytes/s.']; } });

calc({ id: 'cc-uptime', title: 'Availability ("nines") and downtime', desc: 'Percent uptime → allowed downtime', kw: ['uptime', 'availability', 'nines', '99.9', 'SLA', 'downtime per year', 'five nines'], fields: [F('a', 'Availability', 99.9, '%')],
  run: v => { if (!(v.a > 0 && v.a <= 100)) return { err: 'Enter a percentage above 0 and up to 100.' }; const d = (1 - v.a / 100), yr = 365.25 * 86400 * d; return [['Downtime per year', ccDur(yr)], ['Downtime per month (30.44 d)', ccDur(30.4375 * 86400 * d)], ['Downtime per week', ccDur(7 * 86400 * d)], ['Downtime per day', ccDur(86400 * d)], ['Number of nines', v.a < 100 ? -Math.log10(d) : Infinity], 'Two components in series multiply availabilities (99.9% × 99.9% = 99.8%); redundant parts in parallel multiply the unavailabilities.']; } });

calc({ id: 'cc-entropy', title: 'Password strength — entropy and brute-force time', desc: 'Assumes characters or words chosen uniformly at random', kw: ['password entropy', 'brute force', 'password length', 'bits of entropy', 'passphrase', 'diceware', 'password cracking time'], fields: [F('l', 'Length (characters or words)', 12, ''), SEL('c', 'Character set / word list', [[10, 'Digits (10)'], [26, 'Lowercase letters (26)'], [52, 'Upper + lowercase (52)'], [62, 'Letters + digits (62)'], [94, 'All printable ASCII (94)'], [7776, 'Diceware words (7,776)'], [2048, 'BIP-39 words (2,048)']], 94), SEL('g', 'Attacker guess rate', [[100, 'Online, throttled: 100 / s'], [1e4, 'Slow hash (bcrypt-like): 10⁴ / s'], [1e9, 'Fast hash, one GPU: 10⁹ / s'], [1e12, 'Large cracking cluster: 10¹² / s']], 1e9)],
  run: v => { const bits = v.l * Math.log2(v.c), avg = Math.pow(2, bits - 1) / v.g; return [['Entropy', bits, 'bits'], ['Possible combinations', Math.pow(v.c, v.l)], ['Average time to guess (half the space)', ccDur(avg)], ['Worst-case time (whole space)', ccDur(avg * 2)], bits < 40 ? 'Weak: crackable quickly offline.' : bits < 60 ? 'Fair: protect with rate limiting and a slow hash.' : bits < 80 ? 'Good for most accounts.' : 'Very strong.', 'Human-chosen passwords have far less entropy than this formula; use a password manager and multi-factor authentication.']; } });

calc({ id: 'cc-bigo', title: 'Algorithm growth — operations and running time', desc: 'How work grows with input size n', kw: ['Big O', 'algorithm complexity', 'O(n log n)', 'binary search', 'time complexity', 'sorting', 'exponential'], fields: [F('n', 'Input size n', 1e6, ''), SEL('k', 'Complexity', [['1', 'O(1) constant'], ['log', 'O(log n) — binary search'], ['n', 'O(n) — linear scan'], ['nlog', 'O(n log n) — good sorts'], ['n2', 'O(n²) — nested loops, simple sorts'], ['n3', 'O(n³)'], ['2n', 'O(2ⁿ) — brute-force subsets']], 'nlog'), F('r', 'Operations per second', 1e9, 'ops/s')],
  run: v => { const n = v.n, ops = { '1': 1, log: Math.log2(n), n: n, nlog: n * Math.log2(n), n2: n * n, n3: n ** 3, '2n': Math.pow(2, n) }[v.k]; return [['Operations', ops], ['Running time', ccDur(ops / v.r)], ['Binary-search steps for n sorted items', Math.ceil(Math.log2(n + 1))], ['Linear-search average comparisons', (n + 1) / 2], ['n² ÷ n log n ratio', n / Math.log2(n)], 'Constants and caches matter, but growth rate decides which algorithm survives large inputs.']; } });

calc({ id: 'cc-chmod', title: 'Unix permissions — chmod octal and umask', desc: 'Read (4) + write (2) + execute (1) for owner, group, others', kw: ['chmod', 'file permissions', 'octal permissions', '755', '644', 'umask', 'rwx', 'Linux permissions'], fields: [SEL('o', 'Owner', [[7, 'rwx (7)'], [6, 'rw- (6)'], [5, 'r-x (5)'], [4, 'r-- (4)'], [3, '-wx (3)'], [2, '-w- (2)'], [1, '--x (1)'], [0, '--- (0)']], 7), SEL('g', 'Group', [[7, 'rwx (7)'], [6, 'rw- (6)'], [5, 'r-x (5)'], [4, 'r-- (4)'], [3, '-wx (3)'], [2, '-w- (2)'], [1, '--x (1)'], [0, '--- (0)']], 5), SEL('t', 'Others', [[7, 'rwx (7)'], [6, 'rw- (6)'], [5, 'r-x (5)'], [4, 'r-- (4)'], [3, '-wx (3)'], [2, '-w- (2)'], [1, '--x (1)'], [0, '--- (0)']], 5), F('um', 'umask (3 octal digits)', '022', '', { txt: 1 })],
  run: v => { const sy = n => (n & 4 ? 'r' : '-') + (n & 2 ? 'w' : '-') + (n & 1 ? 'x' : '-'), oc = '' + v.o + v.g + v.t, um = String(v.um).trim(); if (!/^[0-7]{3}$/.test(um)) return { err: 'umask must be three octal digits like 022.' }; const f = [...um].map(c => 6 & ~Number(c)), d = [...um].map(c => 7 & ~Number(c)); return [['Octal', oc], ['Symbolic', sy(v.o) + sy(v.g) + sy(v.t)], ['Command', 'chmod ' + oc + ' file'], ['Binary', [v.o, v.g, v.t].map(x => x.toString(2).padStart(3, '0')).join(' ')], ['New files with umask ' + um, f.join('') + '  (' + f.map(sy).join('') + ')'], ['New directories with umask ' + um, d.join('') + '  (' + d.map(sy).join('') + ')'], 'Directories need x to be entered; typical values: 644 files, 755 programs and directories, 600 private keys, 700 private directories.']; } });
