const SM_X = [['Zinc', 7.14, 30.2, 108], ['Lead', 11.34, 28.9, 16], ['Tin', 7.29, 22.0, 50], ['Nickel 200', 8.90, 13.4, 204], ['Magnesium AZ31', 1.77, 26.0, 45], ['Tungsten', 19.25, 4.5, 410], ['Monel 400', 8.80, 13.9, 179], ['Inconel 625', 8.44, 12.8, 205], ['Wrought iron', 7.75, 11.8, 190], ['Tool steel D2', 7.70, 10.4, 210], ['Silver (pure)', 10.49, 19.0, 83], ['Gold (pure)', 19.32, 14.2, 79]];
const SM_ALL = SM_MET.map(r => ({ n: r[0], d: r[5], a: r[7], e: r[8], y: r[9], u: r[10] })).concat(SM_X.map(r => ({ n: r[0], d: r[1], a: r[2], e: r[3] })));
const SM_SEL = SM_ALL.map((m, i) => [String(i), m.n + ' (' + m.d + ' g/cm³)']).concat([['x', 'Custom (enter below)']]);
const smK = 0.0361273, smKft = 62.42796, smKsi = 6.894757;
const smMat = (k, cd) => { if (String(k) === 'x') { if (!(cd > 0)) return null; return { n: 'Custom', d: cd, a: 0, e: 0 }; } return SM_ALL[parseInt(k)] || null; };
const smDimU = SEL('du', 'Cross-section unit', [['25.4', 'inches'], ['1', 'millimetres'], ['10', 'centimetres']], '25.4');
const smLenU = SEL('lu', 'Length unit', [['304.8', 'feet'], ['25.4', 'inches'], ['1000', 'metres'], ['1', 'millimetres']], '304.8');
// 1) Weight by shape
calc({ id: 'sm-weight', title: 'Metal weight by shape (any metal, inch or metric)', desc: 'weight = cross-section area × length × density. Plate/flat: a = width, b = thickness. Round, square, hex: a = size (hex across flats). Tube: a = OD, b = wall. Rect tube: a × b outside, c = wall. Angle: a, b legs, c = thickness (corner radii ignored). Sphere: a = diameter.', kw: ['metal weight', 'steel weight', 'aluminum weight', 'plate weight', 'bar weight', 'tube weight', 'weight per foot', 'kg per metre', 'weight calculator'],
  fields: [SEL('m', 'Metal', SM_SEL, '0'), F('cd', 'Custom density (only if Custom chosen)', '', 'g/cm³', { opt: 1 }), SEL('s', 'Shape', [['plate', 'Plate / sheet / flat bar'], ['round', 'Round bar'], ['square', 'Square bar'], ['hex', 'Hex bar'], ['tube', 'Round tube / pipe'], ['rtube', 'Rectangular tube'], ['angle', 'Angle'], ['sphere', 'Sphere']], 'plate'), smDimU, F('a', 'a', 4), F('b', 'b', 0.25), F('c', 'c (rect tube wall / angle thickness)', 0.25), smLenU, F('l', 'Length', 10), F('n', 'Quantity', 1)],
  run: v => { const m = smMat(v.m, v.cd); if (!m) return { err: 'Enter a custom density above 0.' }; const k = parseFloat(v.du), L = parseFloat(v.lu) * v.l, a = v.a * k, b = v.b * k, c = v.c * k; if (!(a > 0) || !(v.n > 0) || !(v.l > 0)) return { err: 'Size, length and quantity must be above 0.' }; let A;
    switch (v.s) { case 'plate': if (!(b > 0)) return { err: 'Thickness b must be above 0.' }; A = a * b; break; case 'round': A = PI / 4 * a * a; break; case 'square': A = a * a; break; case 'hex': A = 0.8660254 * a * a; break; case 'tube': if (!(b > 0) || b >= a / 2) return { err: 'Wall b must be above 0 and less than half the OD.' }; A = PI * b * (a - b); break; case 'rtube': if (!(b > 0) || !(c > 0) || 2 * c >= Math.min(a, b)) return { err: 'Wall c must be above 0 and less than half of the smaller side.' }; A = 2 * c * (a + b - 2 * c); break; case 'angle': if (!(b > 0) || !(c > 0) || c >= Math.min(a, b)) return { err: 'Thickness c must be above 0 and less than the legs.' }; A = c * (a + b - c); break; default: A = null; }
    let vol; if (v.s === 'sphere') vol = PI / 6 * a * a * a; else vol = A * L; const vcm = vol / 1000, kg = vcm * m.d / 1000, out = [['Volume (each)', vcm, 'cm³'], ['Volume (each)', vcm / 16.387064, 'in³'], ['Mass (each)', kg, 'kg'], ['Weight (each)', kg * 2.2046226, 'lb']];
    if (v.s !== 'sphere') out.push(['Cross-section area', A / 645.16, 'in²'], ['Cross-section area', A, 'mm²'], ['Per metre', A * m.d / 1000, 'kg/m'], ['Per foot', A * 0.3048 * m.d / 1000 * 2.2046226, 'lb/ft']);
    out.push(['Total, ' + v.n + ' piece(s)', kg * v.n, 'kg'], ['Total, ' + v.n + ' piece(s)', kg * v.n * 2.2046226, 'lb'], 'Assumptions: ' + m.n + ' at ' + m.d + ' g/cm³ (typical; alloys vary by a few %), sharp corners, no tolerances, coatings or mill over/under-weight. Billing weights use supplier tables.'); return out; } });
// 2) Density from mass and size
calc({ id: 'sm-density', title: 'Density and specific gravity from mass and size (with likely metals)', desc: 'Measure the mass and either the dimensions, the volume, or the weight in air and in water. The calculator gives density and lists the closest typical metals. Several alloys share a density, so this narrows the list but never proves a grade.', kw: ['density', 'specific gravity', 'identify metal', 'water displacement', 'archimedes', 'density of metal', 'kg/m3', 'lb/in3'],
  fields: [SEL('md', 'Method', [['box', 'Rectangular block (mass, L × W × H)'], ['cyl', 'Solid cylinder (mass, diameter, length)'], ['vol', 'Mass and known volume'], ['arc', 'Weight in air and weight submerged in water']], 'box'), SEL('mu', 'Mass unit', [['1', 'grams'], ['1000', 'kilograms'], ['453.59237', 'pounds'], ['28.349523', 'ounces']], '1'), F('m', 'Mass (or weight in air)', 788), F('ms', 'Weight submerged (method 4)', 688), SEL('lu', 'Length / volume unit', [['10', 'centimetres (cm³)'], ['1', 'millimetres (mm³)'], ['25.4', 'inches (in³)']], '10'), F('x', 'L (or diameter)', 10), F('y', 'W (or length)', 5), F('z', 'H', 2), F('vv', 'Volume (method 3; in the unit cubed)', 100)],
  run: v => { const mu = parseFloat(v.mu), lu = parseFloat(v.lu) / 10, g = v.m * mu; if (!(g > 0)) return { err: 'Mass must be above 0.' }; let vol; if (v.md === 'box') { if (!(v.x > 0 && v.y > 0 && v.z > 0)) return { err: 'Dimensions must be above 0.' }; vol = v.x * v.y * v.z * lu * lu * lu; } else if (v.md === 'cyl') { if (!(v.x > 0 && v.y > 0)) return { err: 'Diameter and length must be above 0.' }; vol = PI / 4 * v.x * v.x * v.y * lu * lu * lu; } else if (v.md === 'vol') { if (!(v.vv > 0)) return { err: 'Volume must be above 0.' }; vol = v.vv * lu * lu * lu; } else { const sub = v.ms * mu; if (!(sub >= 0) || sub >= g) return { err: 'Submerged weight must be less than the weight in air.' }; vol = (g - sub) / 0.998; }
    const d = g / vol, near = SM_ALL.map(m => ({ n: m.n, r: Math.abs(m.d - d) / m.d })).sort((p, q) => p.r - q.r).slice(0, 4), out = [['Density', d, 'g/cm³'], ['Density', d * 1000, 'kg/m³'], ['Density', d * smK, 'lb/in³'], ['Density', d * smKft, 'lb/ft³'], ['Specific gravity (water = 1)', d, ''], ['Volume', vol, 'cm³']];
    near.forEach((q, i) => out.push([(i === 0 ? 'Closest: ' : 'Next: ') + q.n, (q.r * 100).toFixed(1) + ' % away', ''])); out.push('Assumptions: solid, void-free, uniform part; water 0.998 g/cm³ (about 20 °C). A hollow, porous, plated or mixed-material part reads low or wrong. Within about ±2 % several alloys overlap (e.g. 304, 316 and 410 stainless and carbon steel), so density alone cannot identify a grade.'); return out; } });
