    const d1x = A.b[0] - A.a[0], d1y = A.b[1] - A.a[1], d2x = B.b[0] - B.a[0], d2y = B.b[1] - B.a[1], den = d1x * d2y - d1y * d2x; if (Math.abs(den) < 1e-9) continue;
    const t = ((B.a[0] - A.a[0]) * d2y - (B.a[1] - A.a[1]) * d2x) / den, u = ((B.a[0] - A.a[0]) * d1y - (B.a[1] - A.a[1]) * d1x) / den; if (t < 0 || t >= 1 || u < 0 || u >= 1) continue;
    const za = A.a[2] + (A.b[2] - A.a[2]) * t, zb = B.a[2] + (B.b[2] - B.a[2]) * u, U = za < zb ? A : B, tu = za < zb ? t : u, ci = U.si, arc = cum[ci][U.i] + tu * (cum[ci][U.i + 1] - cum[ci][U.i]);
