  s += hk(x3) + `<path d="M${x3} 22 L${x3 - 30} 88 L${x3 - 30} 122 L${x3 + 30} 122 L${x3 + 30} 88 Z" fill="none" stroke="${ACC}" stroke-width="2.5"/>` + box(x3);
