calc({ id: 'mw-weight', title: 'Weight and mass of a part from material and shape', desc: 'mass = density × volume. Choose a material from the database or enter your own density; blocks, plates, round bars, tubes, spheres, or a volume you already know.', kw: ['weight of material', 'weight calculator', 'mass from volume', 'steel plate weight', 'weight of aluminum', 'weight of wood', 'weight of a tank of liquid', 'mass of cylinder', 'tube weight', 'sheet weight'],
  fields: [mwSel('m', 'Material', mwList, String(MW.findIndex(r => r[0] === 'Carbon steel (mild)'))), F('cd', 'Custom density (only if Custom chosen)', '', 'kg/m³', { opt: 1 }), SEL('s', 'Shape', [['b', 'Block / plate: L × W × H'], ['c', 'Round bar or solid cylinder: D × L'], ['t', 'Tube or pipe: OD, wall, L'], ['p', 'Sphere: D'], ['v', 'Known volume (in the unit chosen)']], 'b'), SEL('u', 'Dimension unit', MW_LEN, '0.0254'), F('a', 'L (block) | D (round, sphere) | OD (tube) | volume', 12), F('b', 'W (block) | L (round) | wall (tube)', 6), F('c', 'H (block) | L (tube)', 0.5), F('q', 'Quantity', 1)],
  run: v => { const d = mwDens(v.m, v.cd), k = parseFloat(v.u); if (!d) return { err: 'Enter a custom density above 0.' }; if (!(v.q > 0 && v.a > 0)) return { err: 'Quantity and first dimension must be above 0.' }; let V; const a = v.a * k, b = v.b * k, c = v.c * k; if (v.s === 'b') { if (!(b > 0 && c > 0)) return { err: 'All three dimensions needed.' }; V = a * b * c; } else if (v.s === 'c') { if (!(b > 0)) return { err: 'Length needed.' }; V = PI / 4 * a * a * b; } else if (v.s === 't') { if (!(b > 0 && c > 0 && 2 * b < a)) return { err: 'Tube: wall must be less than half the OD; length above 0.' }; const id = a - 2 * b; V = PI / 4 * (a * a - id * id) * c; } else if (v.s === 'p') V = PI / 6 * a * a * a; else V = v.a * k * k * k; const m = V * d * v.q; return [['Volume (each)', V * 1e3, 'L'], ['Volume (each)', V * 35.3146667, 'ft³'], ['Volume (each)', V * 61023.7441, 'in³'], ['Density used', d, 'kg/m³'], ['Mass', m, 'kg'], ['Weight (mass)', m * 2.2046226, 'lb'], ['Mass', m / 1000, 'tonnes'], ['Mass', m / 907.18474, 'short tons'], ['Weight force', m * 9.80665, 'N'], mwA('solid, no holes, coatings or tolerances; typical density ' + fmt(d, 5) + ' kg/m³ (see the database for the range). A casting, weldment or wet wood can differ by several percent: weigh the real part if the figure matters. For the unit “volume”, the number is in cubic units of the unit chosen.')]; } });
