calc({ id: 'mw-sg', title: 'Specific gravity conversions: density, lb/gal, API gravity and Baumé', desc: 'SG = ρ ÷ ρ(water at 4 °C). API gravity = 141.5 ÷ SG(60/60 °F) − 131.5 for petroleum; Baumé for liquids lighter or heavier than water (modern scale).', kw: ['specific gravity', 'API gravity', 'Baume', 'lb per gallon', 'SG to density', 'density of oil', 'hydrometer', 'relative density', 'degrees API'],
  fields: [SEL('m', 'Know', [['sg', 'Specific gravity'], ['d', 'Density (kg/m³)'], ['lg', 'Pounds per US gallon'], ['api', 'API gravity (°API)']], 'sg'), F('x', 'Value', 0.85), F('r', 'Reference water density (4 °C = 999.97; 15.6 °C = 999.0)', 999.97, 'kg/m³')],
  run: v => { if (!(v.r > 900 && v.r < 1100)) return { err: 'Reference water density should be about 999 to 1000.' }; let sg; if (v.m === 'sg') sg = v.x; else if (v.m === 'd') sg = v.x / v.r; else if (v.m === 'lg') sg = v.x / 0.00834540445 / v.r; else { if (!(v.x > -131.5)) return { err: 'API gravity must be above −131.5.' }; sg = 141.5 / (v.x + 131.5); } if (!(sg > 0)) return { err: 'Specific gravity must be above 0.' }; const d = sg * v.r, api = 141.5 / sg - 131.5, be = sg >= 1 ? 145 - 145 / sg : 140 / sg - 130; return [['Specific gravity', sg, ''], ['Density', d, 'kg/m³'], ['Density', d / 1000, 'g/cm³'], ['Density', d * 0.0624279606, 'lb/ft³'], ['Weight per US gallon', d * 0.00834540445, 'lb'], ['Weight per imperial gallon', d * 0.0100224, 'lb'], ['API gravity', api, '°API'], ['Baumé (modern)', be, '°Bé'], mwA('API gravity applies to petroleum oils at 60 °F with SG 60/60 °F; the reference water density you choose sets the temperature basis (SG at 20 °C relative to water at 4 °C is the usual lab definition). Gases use air as the reference (relative density).')]; } });
