const mxFlatKeys = [5, 10, 3, 8, 1, 6], mxNm = (t, pref) => (pref ? mxF : mxS)[((t % 12) + 12) % 12];
const mxHMS = s => { const t = Math.round(s), h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), x = t % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
const mxNorm = d => ((d % 360) + 360) % 360;
const mxPts16 = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
