const MU_L = ['C', 'D', 'E', 'F', 'G', 'A', 'B'], MU_LP = [0, 2, 4, 5, 7, 9, 11], MU_LF = [0, 2, 4, -1, 1, 3, 5], MU_MAJ = [0, 2, 4, 5, 7, 9, 11];
