const MU_JUST = { 1: [16, 15], 2: [9, 8], 3: [6, 5], 4: [5, 4], 5: [4, 3], 6: [45, 32], 7: [3, 2], 8: [8, 5], 9: [5, 3], 10: [9, 5], 11: [15, 8], 12: [2, 1] };
const MU_PYTH = { 1: [256, 243], 2: [9, 8], 3: [32, 27], 4: [81, 64], 5: [4, 3], 6: [729, 512], 7: [3, 2], 8: [128, 81], 9: [27, 16], 10: [16, 9], 11: [243, 128], 12: [2, 1] };
