    S('al-glossary', 'Almanac terms', [GL([
      ['Aphelion', 'The point in Earth’s orbit farthest from the Sun, early July.'],
      ['Perihelion', 'The point in Earth’s orbit closest to the Sun, early January.'],
      ['Apogee and perigee', 'The Moon’s farthest and closest points to Earth.'],
      ['Equinox', 'One of the two moments when the Sun crosses the celestial equator; day and night are nearly equal.'],
      ['Solstice', 'One of the two moments when the Sun reaches its farthest north or south; the longest or shortest day.'],
      ['Synodic month', 'The 29.53-day cycle from one new moon to the next.'],
      ['Sidereal month', 'The 27.32-day time for the Moon to return to the same place among the stars.'],
      ['Lunation', 'One complete cycle of Moon phases, numbered from the new moon of 6 January 2000.'],
      ['Nodes', 'The two points where the Moon’s orbit crosses the plane of Earth’s orbit; eclipses happen near them.'],
      ['ΔT (delta T)', 'The difference between uniform time and Earth-rotation time; it grows slowly and unpredictably as Earth’s spin varies.'],
      ['Julian Day', 'A continuous count of days used in astronomy, beginning at noon UTC on 1 January 4713 BC.'],
      ['Ecclesiastical full moon', 'The calculated moon date used to set Easter, which may differ from the true full moon by a day or so.'],
      ['Cross-quarter day', 'The midpoint between a solstice and an equinox.'],
      ['Growing degree day', 'A day’s accumulated heat above a crop’s base temperature.'],
      ['Phenology', 'The study of seasonal events in living things, such as leaf-out and flowering.'],
      ['Twilight', 'The sky glow while the Sun is just below the horizon, divided into civil, nautical and astronomical.'],
      ['Zenith', 'The point directly overhead; the Sun’s zenith angle is 90° at the horizon.']
    ])], { kw: ['almanac glossary', 'perihelion', 'synodic', 'sidereal', 'lunation', 'ecliptic', 'delta t', 'phenology'] })
