const GL_FRET = []; for (let n = 1; n <= 24; n++) { const d = L => L * (1 - Math.pow(2, -n / 12)); GL_FRET.push([String(n), fmt(d(25.5), 4), fmt(d(24.75), 4), fmt(d(25.5) * 25.4, 4), fmt(d(648) * 1, 4)]); }
const GL_TUN = Object.keys(glTun).map(k => [glTun[k][0]].concat(glTun[k][1].map(glName)).concat([glTun[k][1].map(m => fmt(glHz(m), 4)).join(' / ')]));
const GL_CHORDS = [['E', '022100'], ['Em', '022000'], ['E7', '020100'], ['Em7', '022030'], ['A', 'x02220'], ['Am', 'x02210'], ['A7', 'x02020'], ['Am7', 'x02010'], ['Asus2', 'x02200'], ['Asus4', 'x02230'], ['D', 'xx0232'], ['Dm', 'xx0231'], ['D7', 'xx0212'], ['Dsus2', 'xx0230'], ['Dsus4', 'xx0233'], ['Dmaj7', 'xx0222'], ['C', 'x32010'], ['C7', 'x32310'], ['Cmaj7', 'x32000'], ['Cadd9', 'x32030'], ['G', '320003'], ['G7', '320001'], ['Gmaj7', '320002'], ['B7', 'x21202'], ['Bm', 'x24432'], ['F', '133211'], ['Fmaj7', 'xx3210'], ['F#m', '244222'], ['B', 'x24442'], ['Bb', 'x13331'], ['E5 (power)', '022xxx'], ['A5 (power)', 'x022xx']];
const glFrets = s => s.split('').map((c, i) => c === 'x' ? null : GL_STR[i] + (+c));
const GL_CHROWS = GL_CHORDS.map(c => [c[0], c[1].split('').join(' '), glFrets(c[1]).map(m => m === null ? '' : glSh[m % 12]).filter(Boolean).join(' ')]);
const glTab = rows => '<pre class="code">' + rows.join('\n') + '</pre>';

CH('guitar', 'guitar', 'Guitar Course: Beginner to Advanced', '🎸',
  'A complete, self-paced guitar course in five levels: first sounds, open chords and strumming; barre chords, the pentatonic scale and the basic techniques; the whole neck and the CAGED system; chord-melody, modes and improvisation; and advanced harmony, speed and composition. It comes with fretboard maps, a chord library, practice plans, a care and setup guide and thirteen calculators for tuning, capo, fret spacing, string tension and practice planning.',
  [
    S('gt-basics', 'Level 0: Your guitar, tuning and how to read the page', [
      T(['Part', 'What it does'], [['Headstock and tuning machines', 'Turn the pegs to change string tension and pitch'], ['Nut', 'Sets the string spacing and the start of the vibrating length'], ['Neck, frets and fingerboard', 'Frets mark the semitones; dots mark frets 3, 5, 7, 9 and 12 (double)'], ['Body and soundhole (acoustic)', 'Amplifies the string vibration'], ['Pickups and controls (electric)', 'Turn string motion into signal; volume and tone knobs'], ['Bridge and saddle', 'Hold the other end of the string and set the intonation'], ['Truss rod', 'A steel rod that adjusts neck curve (relief); a professional adjustment for beginners']], { cap: 'Parts of the guitar' }),
      T(['String', 'Note (standard tuning)', 'Memory phrase', 'Thickness (acoustic, typical)'], [['6th (lowest, thickest)', 'E', 'Eddie', '.053'], ['5th', 'A', 'Ate', '.042'], ['4th', 'D', 'Dynamite', '.032'], ['3rd', 'G', 'Good', '.024'], ['2nd', 'B', 'Bye', '.016'], ['1st (highest, thinnest)', 'E', 'Eddie', '.012']], { cap: 'Standard tuning: E A D G B E (low to high), with the open-string sounds E2 A2 D3 G3 B3 E4' }),
      OL(['<b>Sit</b> with the guitar on your right thigh (right-handers), back straight, forearm resting on the upper bout, neck angled slightly up.', '<b>Fretting hand:</b> thumb behind the neck, fingertips (not pads) just behind the fret, wrist relaxed. Press with just enough force to stop the buzz.', '<b>Picking hand:</b> hold the pick between thumb and the side of the index finger, with only a few millimetres showing. Strum from the elbow and wrist, not the shoulder.', '<b>Tune</b> with a clip-on tuner: each string up to pitch. Tune before every session; new strings go flat for the first days.', '<b>Keep the first sessions short:</b> 15 minutes twice a day beats an hour once a week. Fingertips will ache for 2–3 weeks, then toughen.']),
      H('Reading chord boxes and tablature'),
      P('A <b>tab</b> shows six lines, one per string, with the thinnest string on top. A number is the fret to press (0 is open). Numbers stacked in a column are played together. A <b>chord box</b> is the neck seen head-on; here a chord is written as six characters from the lowest string to the highest, where <b>x</b> means do not play that string and 0 means open.'),
      glTab(['e|-----0-----|', 'B|-----1-----|    C major arpeggio', 'G|-----0-----|    (x32010: play the strings one at a time)', 'D|-----2-----|', 'A|-----3-----|', 'E|-----------|']),
      T(['Tuning', '6th', '5th', '4th', '3rd', '2nd', '1st', 'Frequencies in Hz (6th to 1st)'], GL_TUN, { cap: 'Common tunings (A = 440 Hz)' }),
      CALC('gt-tuning'), CALC('gt-cents')
    ], { kw: ['guitar basics', 'beginner guitar', 'parts of a guitar', 'tuning guitar', 'standard tuning', 'EADGBE', 'tablature', 'read tab', 'chord diagram', 'holding a guitar', 'posture', 'pick grip', 'drop d', 'dadgad', 'open tunings'], see: ['music-theory|Music theory'] }),

    S('gt-level1', 'Level 1: First chords, strumming and first songs (weeks 1–8)', [
      P('Goal: play open chords cleanly, change between them in time and play a handful of songs. Learn one new chord every few days; do not move on until you can strum all six strings with no buzz and change in time to a slow metronome.'),
      T(['Chord', 'Frets (6th to 1st)', 'Notes by string (low to high)'], GL_CHROWS, { cap: 'The open-chord library: frets from the 6th (low E) string to the 1st (high E)', filter: true, idx: true }),
      T(['Week', 'Learn', 'Practice'], [['1', 'Em, Am (two fingers); strum down on the beat', 'Tune up; strum 4 down-strums per chord at 60 BPM; change between Em and Am'], ['2', 'D, E, A', 'Change between any two chords in the key of A (A, D, E)'], ['3', 'C, G, Dm', 'Slow three-chord loop G – C – D; keep the strum going while the left hand moves'], ['4', 'The down–up pattern: D D U U D U', 'Mute the strings with the left hand; keep the right arm moving constantly'], ['5', 'A7, E7, D7', 'Play a 12-bar blues in A (see below) at 70 BPM'], ['6', 'Fingerpicking pattern p-i-m-a on an Am chord', 'Pick the strings one at a time: 5-3-2-1'], ['7', 'Sus chords (Asus2, Dsus4) and Cadd9', 'Learn a song with four chords: G – D – Em – C'], ['8', 'First F chord (Fmaj7 or small barre)', 'Perform a song start to finish with no stopping']], { cap: 'An eight-week start' }),
      H('Strumming patterns'),
      glTab(['Count:   1 & 2 & 3 & 4 &', 'Basic:   D   D   D   D          (all down: quarter notes)', 'Eighths: D D D D D D D D       (all down)', 'Pop:     D   D U   U D U       (the classic D–DU–UDU)', 'Folk:    D   D U D U D U', 'Ballad:  D     D U     D U']),
      H('Four chords for hundreds of songs'),
      T(['Progression', 'Roman numerals', 'In G', 'In C', 'In D', 'In A'], [['Pop', 'I – V – vi – IV', 'G D Em C', 'C G Am F', 'D A Bm G', 'A E F#m D'], ['50s doo-wop', 'I – vi – IV – V', 'G Em C D', 'C Am F G', 'D Bm G A', 'A F#m D E'], ['Three-chord rock', 'I – IV – V', 'G C D', 'C F G', 'D G A', 'A D E'], ['Folk', 'I – IV – I – V', 'G C G D', 'C F C G', 'D G D A', 'A D A E'], ['Minor feel', 'vi – IV – I – V', 'Em C G D', 'Am F C G', 'Bm G D A', 'F#m D A E']], { cap: 'Common progressions in easy open-chord keys' }),
      H('12-bar blues in A (the most useful form in popular music)'),
      glTab(['| A7  | A7  | A7  | A7  |', '| D7  | D7  | A7  | A7  |', '| E7  | D7  | A7  | E7  |']),
      T(['Problem', 'Likely cause', 'Fix'], [['Buzzing', 'Finger not close enough behind the fret, or too light', 'Move the fingertip right behind the fret wire; add pressure; check that the neighbouring finger is not touching the string'], ['Muted string (dead sound)', 'A finger is touching the next string', 'Arch the fingers; play on the tips; angle the wrist out'], ['Sore fingertips', 'Normal in weeks 1–3', 'Short sessions; stop when it hurts; do not use rubbing alcohol or glue'], ['Slow chord changes', 'Lifting all fingers and replacing them one at a time', 'Practice “anchor fingers” that stay on the same string; move the whole shape at once'], ['Strum falls apart when you change chords', 'The right hand waits for the left', 'Keep the strumming arm moving; skip a strum rather than stop the beat']], { cap: 'Fixing the usual beginner problems' }),
      CALC('gt-strum'), CALC('gt-chord'), CALC('gt-capo')
    ], { kw: ['open chords', 'beginner chords', 'first guitar chords', 'strumming patterns', 'chord progressions', '12 bar blues', 'em am d g c', 'chord changes', 'buzzing', 'sore fingers', 'learn guitar', 'first songs', 'four chord songs'], see: ['music-theory|Music theory'] }),

    S('gt-level2', 'Level 2: Barre chords, power chords, pentatonics and techniques (months 3–8)', [
      P('At this level the whole neck begins to open up. Two movable chord shapes (the <b>E shape</b> and the <b>A shape</b>) give you every major and minor chord; the pentatonic scale gives you the first solos.'),
      T(['Shape', 'Frets (6th to 1st), at the nut', 'How to move it', 'Example'], [['E-shape major barre', '0 2 2 1 0 0', 'Barre across all strings at the root fret; the root is on the 6th string', 'F = fret 1, G = fret 3, A = fret 5, B = fret 7'], ['E-shape minor barre', '0 2 2 0 0 0', 'Same, with the 3rd-finger note released', 'Fm = fret 1, F#m = fret 2, Am = fret 5, Bm = fret 7'], ['A-shape major barre', 'x 0 2 2 2 0', 'Barre on the 5th string root', 'Bb = fret 1, B = fret 2, C = fret 3, D = fret 5'], ['A-shape minor barre', 'x 0 2 2 1 0', 'Same with the middle note lowered', 'Bm = fret 2, Cm = fret 3'], ['Power chord (5)', 'root and fifth, plus octave', 'Two or three strings; the root is the lowest note; slide it anywhere', 'G5 = 3 5 5 on the 6th, 5th, 4th'], ['Dominant 7 barre', '0 2 0 1 0 0', 'E7 shape at any fret', 'F7 = fret 1']], { cap: 'Movable barre chord shapes (the E shape means the open-E-chord fingering moved up with a barre)' }),
      OL(['Place the index finger flat across the strings with the edge of the finger turned slightly toward the nut.', 'Keep the thumb behind the neck, near the middle.', 'Add the E-shape fingering with the other three fingers.', 'Squeeze with the whole hand (arm weight, not thumb strength). If it will not ring, move the elbow in and the wrist away.', 'Practice by sliding the shape up the neck while naming each chord.']),
      T(['Technique', 'How it is played', 'Notation'], [['Hammer-on', 'Fret a note, then bring another finger down hard on a higher fret without picking again', 'h'], ['Pull-off', 'From a fretted note, pull the finger away sideways to sound a lower note', 'p'], ['Slide', 'Move the fretting finger along the string to another fret', '/ (up) or \\ (down) or s'], ['Bend', 'Push the string sideways to raise the pitch (half step = about 1 fret, full step = 2 frets)', 'b, with the target fret'], ['Vibrato', 'Rock the string back and forth (or the wrist) to wobble the pitch', '~'], ['Palm mute', 'Rest the side of the picking hand lightly on the strings near the bridge', 'P.M.'], ['Alternate picking', 'Down-up-down-up, strictly, on every note', '⊓ and ∨'], ['Fingerpicking', 'Thumb on the low strings, fingers on the high strings (p, i, m, a)', 'p i m a']], { cap: 'Essential techniques' }),
      H('The minor pentatonic: your first solo scale'),
      glTab(['A minor pentatonic, box 1 (root A on the 5th fret):', 'e|--5--8-----------|', 'B|--5--8-----------|', 'G|--5--7-----------|', 'D|--5--7-----------|', 'A|--5--7-----------|', 'E|--5--8-----------|']),
      UL(['Play it up and down slowly with a metronome, then in groups of three, then four.', 'The five notes are A C D E G. Landing on A, C or E sounds stable; adding the blue note Eb (fret 6 on the 5th string) gives the blues scale.', 'Over a 12-bar blues in A, play box 1 and bend the 3rd-string note at the 7th fret up a whole step.', 'Learn the major pentatonic as the same shapes starting three frets lower: A major pentatonic is the same notes as F# minor pentatonic.']),
      CALC('gt-scale'), CALC('gt-capofind'), CALC('gt-ramp')
    ], { kw: ['barre chords', 'power chords', 'pentatonic scale', 'minor pentatonic', 'hammer on', 'pull off', 'bending', 'vibrato', 'palm muting', 'alternate picking', 'fingerpicking', 'first solo', 'e shape', 'a shape', 'slide'], see: ['music-theory|Music theory'] }),

    S('gt-level3', 'Level 3: The whole neck, CAGED, modes and rhythm (year 1–2)', [
      P('The <b>CAGED system</b> shows that every major chord on the neck is one of five open shapes (C, A, G, E, D) moved up the neck, and that the five shapes link head-to-tail around the fretboard. Learn each shape and the scale that lives around it.'),
      T(['Key of C', 'Shape', 'Root position on the neck'], [['C shape', 'x32010', 'Open position (frets 0–3); the root C is on the 5th string, fret 3'], ['A shape', 'x02220', 'Barre at fret 3 (root on the 5th string)'], ['G shape', '320003', 'Frets 5–8 (not a barre); the root C is on the 6th string, fret 8'], ['E shape', '022100', 'Barre at fret 8; the root C is on the 6th string, fret 8'], ['D shape', 'xx0232', 'Around fret 10; the root C is on the 4th string, fret 10']], { cap: 'The C chord in five places (shapes named after the open chord they resemble)' }),
      T(['Mode', 'Formula (from major)', 'Notes in C', 'Sound and use'], [['Ionian', '1 2 3 4 5 6 7', 'C D E F G A B', 'Major scale: bright and stable'], ['Dorian', '1 2 b3 4 5 6 b7', 'D E F G A B C', 'Minor with a brighter 6th (funk, jazz, Santana)'], ['Phrygian', '1 b2 b3 4 5 b6 b7', 'E F G A B C D', 'Dark and Spanish'], ['Lydian', '1 2 3 #4 5 6 7', 'F G A B C D E', 'Dreamy, floating (film music, Satriani)'], ['Mixolydian', '1 2 3 4 5 6 b7', 'G A B C D E F', 'Dominant: blues-rock, country, Celtic'], ['Aeolian', '1 2 b3 4 5 b6 b7', 'A B C D E F G', 'Natural minor'], ['Locrian', '1 b2 b3 4 b5 b6 b7', 'B C D E F G A', 'Unstable; used over half-diminished chords']], { cap: 'The seven modes, all drawn from the key of C major' }),
      T(['Chord type', 'Formula', 'Open-chord example', 'Where it is used'], [['Major 7', 'R 3 5 7', 'Cmaj7 x32000', 'Jazz, soft pop'], ['Dominant 7', 'R 3 5 b7', 'G7 320001', 'Blues, country, V chord'], ['Minor 7', 'R b3 5 b7', 'Am7 x02010', 'Soul, jazz, ii chord'], ['Add 9', 'R 3 5 9', 'Cadd9 x32030', 'Open, ringing pop sound'], ['Sus 2 / sus 4', 'R 2 5 / R 4 5', 'Asus2 x02200', 'Tension and release'], ['Diminished', 'R b3 b5', 'B dim x2343x', 'Passing chord'], ['6 and 9', 'R 3 5 6 / R 3 5 b7 9', 'C6 x32210', 'Jazz and blues endings']], { cap: 'Chord extensions that colour a progression' }),
      UL(['<b>Triads on the top strings:</b> play three-note chords on strings 1–3, 2–4 or 3–5 in all inversions. They are the vocabulary of funk and clean rhythm guitar.', '<b>Rhythm:</b> practice 16th-note strumming with a muted “ghost” hand; accent beats 2 and 4. The right hand never stops.', '<b>Ear training:</b> sing each note you play. Learn to identify the intervals by their songs (a fifth is the Star Wars theme; a minor third is “Greensleeves”).', '<b>Learn the notes</b> on the 6th and 5th strings (the fretboard map below) and name them aloud as you slide.', '<b>Learn songs by ear</b> and transcribe one solo a month; your own phrasing starts as other people’s.']),
      T(['Fret', 'E (6th)', 'A', 'D', 'G', 'B', 'E (1st)', 'Marker'], GL_MAP, { cap: 'The fretboard map in standard tuning, frets 0 to 12 (the notes repeat from the 12th fret)' }),
      CALC('gt-note')
    ], { kw: ['caged system', 'modes', 'dorian', 'mixolydian', 'lydian', 'phrygian', 'chord extensions', 'seventh chords', 'sus chords', 'fretboard notes', 'learn the fretboard', 'triads', 'rhythm guitar', 'ear training', 'transcribing', 'intermediate guitar'], see: ['music-theory|Music theory'] }),

    S('gt-level4', 'Level 4: Advanced harmony, speed and improvisation (year 2+)', [
      T(['Topic', 'What to learn', 'How to practice it'], [['Jazz voicings', 'Shell voicings (root, 3rd, 7th) and drop-2 chords on strings 6-5-4-3, 5-4-3-2 and 4-3-2-1', 'Play the ii – V – I (Dm7 – G7 – Cmaj7) in all twelve keys'], ['Melodic and harmonic minor', 'Harmonic minor over the V7 chord; melodic minor and its modes (altered scale over dominant chords)', 'Play each scale in two positions and resolve to the chord’s 3rd'], ['Arpeggios', 'Major 7, minor 7, dominant 7 and half-diminished, in two octaves', 'Outline the chords of a tune with arpeggios, one per bar'], ['Sweep picking', 'One continuous pick motion across three to five strings, notes ringing separately', 'Practice a 3-string major triad very slowly; use fretting-hand muting to keep each note short'], ['Tapping', 'Tap with the picking-hand finger at a fret above the fretted notes: tap, pull-off, pull-off', 'Start with a three-note pattern (tap 12, pull to 8, pull to 5)'], ['Hybrid picking', 'Pick with a pick and the middle/ring fingers together, to jump between non-adjacent strings', 'Pick the bass string with the pick, then the 2nd and 1st with the fingers'], ['Alternate tunings', 'Drop D, DADGAD, open G, open D and open E for slide and fingerstyle', 'Re-learn the neck in each; see the tuning table'], ['Improvising over changes', 'Guide tones: target the 3rd and 7th of each chord', 'Play only chord tones; then add scale tones between them'], ['Composition and arranging', 'Write a melody, harmony, bass line, form (verse, chorus, bridge) and an ending', 'Write a 16-bar tune a month; record every one'], ['Recording and production', 'Gain staging, a mic or DI, room and monitoring, simple editing and mixing', 'Record yourself playing along with a drum loop and listen back critically']], { cap: 'Advanced topics and practice approaches' }),
      T(['Skill check', 'You can…'], [['Level 1', 'Play 12 open chords, change four of them in time at 80 BPM and strum a three-chord song'], ['Level 2', 'Play barre chords with a clean ring, the minor pentatonic in all five positions and a 12-bar blues with a solo'], ['Level 3', 'Name every note on the 6th and 5th strings, play the CAGED shapes in any key, build and use modes and 7th chords'], ['Level 4', 'Improvise over a ii – V – I using chord tones, play arpeggios at 120 BPM in 16ths, arrange a song for solo guitar, and write and record original music']], { cap: 'A self-assessment ladder' }),
      NOTE('Technique tips: use a metronome for every technique; practise at a speed where every note is clean; speed up in steps of 2–5 BPM (use the tempo ramp calculator). Stop at the first sign of pain or numbness in your hand or wrist; rest, check your posture and grip and, if it persists, see a clinician (hand and wrist injuries in guitarists are common and treatable).'),
      CALC('gt-delay'), CALC('gt-tension')
    ], { kw: ['advanced guitar', 'jazz guitar', 'sweep picking', 'tapping', 'hybrid picking', 'improvisation', 'ii v i', 'melodic minor', 'altered scale', 'drop 2 voicings', 'composition', 'recording guitar', 'alternate tuning', 'shell voicings', 'chord tones'], see: ['music-theory|Music theory'] }),

    S('gt-fretboard', 'Fretboard geometry and tunings', [
      T(['Fret', 'Distance from the nut: 25.5 in (Fender)', '24.75 in (Gibson)', '25.5 in scale, in mm', '648 mm scale, in mm'], GL_FRET, { cap: 'Distance from the nut to each fret (inches unless stated)' }),
      UL(['Fret 12 is exactly half the scale length; fret 19 is one third from the bridge; fret 24 is one quarter from the bridge.', 'The rule of 17.817: each fret sits 1/17.817 of the remaining string length beyond the previous fret.', 'Common scale lengths: Fender-style 25.5 in (648 mm); Gibson-style 24.75 in (629 mm); PRS 25 in (635 mm); classical 650 mm; many 3/4 size guitars about 580 mm.']),
      CALC('gt-fret')
    ], { kw: ['fret spacing table', 'scale length', 'fender scale', 'gibson scale', 'rule of 17.817', 'luthier', 'fret 12 half'], see: ['music-theory|Music theory'] }),

    S('gt-practice', 'Practice routines and learning plans', [
      T(['Block', 'Minutes', 'What to do'], [['Warm up', '5', 'Chromatic exercise, 1-2-3-4 on each string, slowly'], ['Technique', '10', 'One skill (barre chords, bends, alternate picking) with a metronome'], ['New material', '10', 'A new chord, scale or song section, in small pieces'], ['Repertoire', '10', 'Play two songs you already know, start to finish'], ['Creative', '5', 'Improvise, write or play along to a backing track']], { cap: 'A 40-minute daily session' }),
      UL(['<b>Slow is fast:</b> play everything at a speed where it is perfect and let the speed come.', '<b>Chunk it:</b> break a hard passage into 2–4 note pieces; join them at the end.', '<b>Record yourself</b> weekly; you hear timing mistakes that you do not feel.', '<b>Play with others</b> as soon as you can: a friend, a jam, a band, a backing track.', '<b>Learn songs you love</b>; motivation matters more than the “perfect” method.', '<b>Rest:</b> take one or two days off a week; the hands and brain consolidate during rest.']),
      CALC('gt-hours')
    ], { kw: ['practice routine', 'practice schedule', 'how to practice guitar', 'daily practice', 'warm up', 'learning plan', 'metronome practice', 'practice tips'], see: ['gt-level1|Level 1'] }),

    S('gt-gear', 'Gear, setup and care', [
      T(['Item', 'Guide'], [['Acoustic strings', '80/20 bronze or phosphor bronze, light (.012–.053) for beginners'], ['Electric strings', 'Nickel-wound .010–.046 standard; .009 easier to bend; .011 fuller tone'], ['Nylon strings (classical)', 'Normal or hard tension; classical necks are wider'], ['Pick', 'Thin (.5 mm) for strumming, medium (.73 mm), heavy (1.0 mm +) for lead'], ['Tuner', 'Clip-on, in tune with A = 440 Hz'], ['Capo', 'A spring-loaded or strap capo that does not pull strings sharp'], ['Strap', 'Needed for standing; use strap locks on electrics']], { cap: 'What to buy' }),
      OL(['<b>Change strings</b> every 1–3 months (or when they sound dull): one at a time to keep the bridge and neck tension steady; stretch each new string gently and retune.', '<b>Clean</b> the fretboard with a dry cloth; oil unfinished rosewood or ebony a couple of times a year.', '<b>Humidity:</b> keep acoustic guitars at 40–55% relative humidity and avoid heat and sun; use a humidifier in a dry winter.', '<b>Action</b> (string height) at the 12th fret is typically 1.5–2.0 mm on the bass side and 1.2–1.6 mm on the treble side on an acoustic or electric. Have a luthier set the truss rod and intonation.', '<b>Intonation:</b> the 12th-fret note should match the 12th-fret harmonic; if sharp, lengthen the string at the saddle; if flat, shorten it.']),
      T(['Signal chain (electric)', 'Role'], [['Guitar', 'Source'], ['Tuner, compressor, wah', 'Early in the chain'], ['Overdrive, distortion, fuzz', 'Gain'], ['Modulation (chorus, flanger, phaser, tremolo)', 'After gain'], ['Delay, reverb', 'Last, or in the amp’s effects loop'], ['Amplifier and speaker', 'Tone and volume']], { cap: 'A common order for pedals' }),
      WARN('Loud amplifiers and headphones damage hearing permanently. Use hearing protection at rehearsals; keep headphone volume below the level where you cannot hear someone speaking next to you. Do not open a tube amplifier: it contains lethal voltages even when unplugged.')
    ], { kw: ['guitar strings', 'string change', 'guitar setup', 'action', 'truss rod', 'intonation', 'humidity', 'guitar pedals', 'signal chain', 'amplifier', 'guitar care', 'guitar picks', 'capo choice', 'hearing protection'], see: ['electrical|Electrical'] }),

    S('gt-glossary', 'Guitar terms', [GL([
      ['Action', 'The height of the strings above the frets.'],
      ['Barre', 'Pressing several strings at once with one finger.'],
      ['Bend', 'Pushing a string sideways to raise its pitch.'],
      ['CAGED', 'The system of five open chord shapes (C, A, G, E, D) that cover the neck.'],
      ['Capo', 'A clamp that shortens the strings, raising the key.'],
      ['Chord', 'Three or more notes sounded together.'],
      ['Drop D', 'A tuning with the 6th string lowered a whole step to D.'],
      ['Fret', 'A raised metal strip that marks a semitone.'],
      ['Hammer-on / pull-off', 'Sounding a note by fretting or releasing a finger without picking.'],
      ['Intonation', 'How accurately the guitar plays in tune up and down the neck.'],
      ['Nut', 'The grooved piece that spaces the strings at the headstock end.'],
      ['Pentatonic', 'A five-note scale; the basis of most rock and blues solos.'],
      ['Power chord', 'A two-note (root and fifth) chord, often doubled at the octave.'],
      ['Saddle', 'The piece the strings rest on at the bridge.'],
      ['Scale length', 'The vibrating length from nut to saddle.'],
      ['Tablature (tab)', 'Notation showing strings and frets instead of notes.'],
      ['Tremolo picking', 'Picking one note very fast and continuously.'],
      ['Truss rod', 'A rod inside the neck that adjusts its curve.'],
      ['Voicing', 'The particular arrangement of a chord’s notes on the strings.']
    ])], { kw: ['guitar glossary', 'guitar terms', 'barre', 'caged', 'capo', 'intonation', 'saddle', 'truss rod', 'tab'] })
  ]);
/* ===== CATEGORY 19: VISUAL BASIC (VB.NET) ===== */
const vbCode = s => '<pre class="code">' + s.replace(/^\n/, '').replace(/\s+$/, '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</pre>';
