const VB_TYPES = [['Boolean', 'System.Boolean', '1 byte (2 in older docs)', 'True or False', 'False'], ['Byte', 'System.Byte', '1', '0 to 255', '0'], ['SByte', 'System.SByte', '1', '−128 to 127', '0'], ['Short', 'System.Int16', '2', '−32,768 to 32,767', '0'], ['UShort', 'System.UInt16', '2', '0 to 65,535', '0'], ['Integer', 'System.Int32', '4', '−2,147,483,648 to 2,147,483,647', '0'], ['UInteger', 'System.UInt32', '4', '0 to 4,294,967,295', '0'], ['Long', 'System.Int64', '8', '−9.22 × 10^18 to 9.22 × 10^18', '0'], ['ULong', 'System.UInt64', '8', '0 to 1.84 × 10^19', '0'], ['Single', 'System.Single', '4', '±1.5 × 10^−45 to ±3.4 × 10^38 (about 7 digits)', '0'], ['Double', 'System.Double', '8', '±5.0 × 10^−324 to ±1.8 × 10^308 (15–17 digits)', '0'], ['Decimal', 'System.Decimal', '16', '±79,228,162,514,264,337,593,543,950,335 (28–29 digits, exact decimals)', '0'], ['Char', 'System.Char', '2', 'One UTF-16 code unit', 'Nothing (ChrW(0))'], ['String', 'System.String', '2 per char + overhead', 'Up to about 2 billion characters', 'Nothing'], ['Date', 'System.DateTime', '8', '0001-01-01 to 9999-12-31', '#1/1/0001 12:00:00 AM#'], ['Object', 'System.Object', '4 or 8 (reference)', 'Anything', 'Nothing']];
