FORM('tape-temp', 'Steel tape temperature correction', 'Construction', 'C_t = 0.0000065 (T − T_s) L', 'T|field temperature|°F; Ts~T_s|standard temperature (usually 68)|°F; L|measured length|ft; Ct~C_t|correction (add if warmer)|ft', 'Steel tape; coefficient ≈ 6.5 × 10⁻⁶ per °F.', 'Ct', v => 0.0000065 * (v.T - v.Ts) * v.L, { T: 95, Ts: 68, L: 300 }, ['tape-corr', 'sv-dist'], ['surveying']);
FORM('curv-refr', 'Curvature and refraction correction', 'Construction', 'h = 0.0675 K²', 'K|sight distance|km; h|combined correction|m', 'Standard refraction; small distances only.', 'h', v => 0.0675 * v.K * v.K, { K: 2 }, ['curv-refr'], ['surveying']);
FORM('closure', 'Traverse linear misclosure', 'Construction', 'e = √(ΔN² + ΔE²)', 'dN~ΔN|sum of northings error|; dE~ΔE|sum of eastings error|; e|linear misclosure|', 'Closed traverse; compare e with the perimeter for the precision ratio.', 'e', v => Math.hypot(v.dN, v.dE), { dN: 0.03, dE: 0.04 }, ['sv-traverse'], ['surveying']);
// ---- Fluid mechanics
FORM('flow-continuity', 'Continuity equation', 'Fluid mechanics', 'A₁ v₁ = A₂ v₂', 'A1~A₁|area at 1|; v1~v₁|velocity at 1|; A2~A₂|area at 2|; v2~v₂|velocity at 2|', 'Incompressible, steady flow in a full conduit.', 'v2', v => v.A1 * v.v1 / v.A2, { A1: 0.02, v1: 2, A2: 0.01 }, ['pp-flow', 'pt-flow'], ['pipe-fittings', 'pumps-tanks']);
FORM('flow-q', 'Volume flow rate', 'Fluid mechanics', 'Q = A v', 'A|flow area|m²; v|mean velocity|m/s; Q|volume flow|m³/s', '', 'Q', v => v.A * v.v, { A: 0.0079, v: 2 }, ['pp-flow', 'wt-flow'], ['pipe-fittings', 'water']);
FORM('pipe-velocity', 'Velocity in a round pipe', 'Fluid mechanics', 'v = 4 Q ÷ (π D²)', 'Q|flow|m³/s; D|inside diameter|m; v|velocity|m/s', 'Full pipe.', 'v', v => 4 * v.Q / (Math.PI * v.D * v.D), { Q: 0.01, D: 0.1 }, ['pp-flow', 'pipe-flow'], ['pipe-fittings']);
FORM('hydrostatic', 'Hydrostatic pressure', 'Fluid mechanics', 'P = ρ g h', 'rho~ρ|fluid density|kg/m³; g|gravity|m/s²; h|depth|m; P|gauge pressure|Pa', 'Fluid at rest; gauge pressure (add atmospheric for absolute).', 'P', v => v.rho * v.g * v.h, { rho: 1000, g: G0, h: 10 }, ['wt-hydro', 'cp-hydro'], ['water', 'pumps-tanks']);
FORM('bernoulli', 'Bernoulli equation (pressure at point 2)', 'Fluid mechanics', 'P₂ = P₁ + ½ρ(v₁² − v₂²) + ρ g (h₁ − h₂)', 'rho~ρ|density|kg/m³; P1~P₁|pressure at 1|Pa; v1~v₁|velocity at 1|m/s; v2~v₂|velocity at 2|m/s; h1~h₁|elevation of 1|m; h2~h₂|elevation of 2|m; P2~P₂|pressure at 2|Pa', 'Steady, incompressible, frictionless flow along a streamline.', 'P2', v => v.P1 + 0.5 * v.rho * (v.v1 ** 2 - v.v2 ** 2) + v.rho * G0 * (v.h1 - v.h2), { rho: 1000, P1: 200000, v1: 2, v2: 4, h1: 5, h2: 0 }, ['pipe-flow'], ['pipe-fittings', 'pumps-tanks']);
FORM('reynolds', 'Reynolds number', 'Fluid mechanics', 'Re = ρ v D ÷ μ', 'rho~ρ|density|kg/m³; v|velocity|m/s; D|pipe diameter|m; mu~μ|dynamic viscosity|Pa·s; Re|Reynolds number|', 'Laminar below about 2,000, turbulent above about 4,000 in pipes.', 'Re', v => v.rho * v.v * v.D / v.mu, { rho: 1000, v: 2, D: 0.05, mu: 0.001 }, ['pipe-flow', 'pp-flow'], ['pipe-fittings']);
FORM('darcy', 'Darcy–Weisbach head loss', 'Fluid mechanics', 'h_f = f (L ÷ D) (v² ÷ 2g)', 'f|Darcy friction factor|; L|pipe length|m; D|inside diameter|m; v|velocity|m/s; hf~h_f|head loss|m', 'Full pipe; f from the Moody chart or Colebrook equation.', 'hf', v => v.f * (v.L / v.D) * v.v * v.v / (2 * G0), { f: 0.02, L: 100, D: 0.1, v: 2 }, ['pipe-flow', 'pt-head'], ['pipe-fittings', 'pumps-tanks']);
FORM('hazen', 'Hazen–Williams head loss (SI)', 'Fluid mechanics', 'h_f = 10.67 L Q^1.852 ÷ (C^1.852 D^4.87)', 'L|pipe length|m; Q|flow|m³/s; C|roughness coefficient|; D|inside diameter|m; hf~h_f|head loss|m', 'Water at ordinary temperature, turbulent flow; C ≈ 100–150.', 'hf', v => 10.67 * v.L * v.Q ** 1.852 / (v.C ** 1.852 * v.D ** 4.87), { L: 100, Q: 0.01, C: 130, D: 0.1 }, ['pipe-size', 'pipe-flow'], ['pipe-fittings', 'water']);
FORM('pump-power', 'Pump shaft power', 'Fluid mechanics', 'P = ρ g Q H ÷ η', 'rho~ρ|density|kg/m³; Q|flow|m³/s; H|total head|m; eta~η|pump efficiency (0–1)|; P|shaft power|W', 'Add motor efficiency for electrical input.', 'P', v => v.rho * G0 * v.Q * v.H / v.eta, { rho: 1000, Q: 0.02, H: 30, eta: 0.7 }, ['pump-power', 'pt-power'], ['pumps-tanks']);
FORM('torricelli', 'Torricelli’s speed of efflux', 'Fluid mechanics', 'v = √(2 g h)', 'g|gravity|m/s²; h|head above the opening|m; v|exit speed|m/s', 'Ideal; multiply by a discharge coefficient for real openings.', 'v', v => Math.sqrt(2 * v.g * v.h), { g: G0, h: 5 }, ['pt-drain', 'tank-drain'], ['pumps-tanks']);
FORM('orifice', 'Orifice discharge', 'Fluid mechanics', 'Q = C_d A √(2 g h)', 'Cd~C_d|discharge coefficient (about 0.6)|; A|orifice area|m²; h|head|m; Q|flow|m³/s', 'Sharp-edged orifice, free discharge.', 'Q', v => v.Cd * v.A * Math.sqrt(2 * G0 * v.h), { Cd: 0.61, A: 0.001, h: 2 }, ['pt-drain', 'tank-drain'], ['pumps-tanks']);
FORM('joukowsky', 'Water hammer pressure surge', 'Fluid mechanics', 'ΔP = ρ a Δv', 'rho~ρ|density|kg/m³; a|wave speed in the pipe|m/s; dv~Δv|sudden velocity change|m/s; dP~ΔP|pressure rise|Pa', 'Closure faster than 2L/a (instantaneous).', 'dP', v => v.rho * v.a * v.dv, { rho: 1000, a: 1200, dv: 1 }, ['water-hammer'], ['pipe-fittings', 'water']);
FORM('buoyancy', 'Buoyant force (Archimedes)', 'Fluid mechanics', 'F_b = ρ g V', 'rho~ρ|fluid density|kg/m³; V|displaced volume|m³; Fb~F_b|buoyant force|N', 'Fully or partly submerged body.', 'Fb', v => v.rho * G0 * v.V, { rho: 1000, V: 0.05 }, ['cp-buoyancy'], ['materials-weights']);
FORM('dynamic-pressure', 'Dynamic pressure', 'Fluid mechanics', 'q = ½ ρ v²', 'rho~ρ|density|kg/m³; v|speed|m/s; q|dynamic pressure|Pa', 'Wind load estimates use q with a pressure coefficient.', 'q', v => 0.5 * v.rho * v.v * v.v, { rho: 1.2, v: 30 }, ['wth-wind'], ['weather']);
FORM('manning', 'Manning’s equation', 'Fluid mechanics', 'V = (1 ÷ n) R^(2/3) S^(1/2)', 'n|roughness coefficient|; R|hydraulic radius|m; S|channel slope (m/m)|; V|mean velocity|m/s', 'Open-channel, uniform flow, SI units.', 'V', v => Math.pow(v.R, 2 / 3) * Math.sqrt(v.S) / v.n, { n: 0.013, R: 0.5, S: 0.001 }, ['wt-flow'], ['water']);
FORM('wind-chill-f', 'Wind chill (US NWS formula)', 'Fluid mechanics', 'WC = 35.74 + 0.6215 T − 35.75 V^0.16 + 0.4275 T V^0.16', 'T|air temperature|°F; V|wind speed|mph; WC|wind chill temperature|°F', 'T ≤ 50 °F and V ≥ 3 mph. An index of exposed-skin cooling, not a thermometer reading.', 'WC', v => 35.74 + 0.6215 * v.T - 35.75 * v.V ** 0.16 + 0.4275 * v.T * v.V ** 0.16, { T: 20, V: 15 }, ['wind-chill', 'wth-chill'], ['weather']);
FORM('dew-point', 'Dew point (Magnus approximation)', 'Fluid mechanics', 'α = ln(RH/100) + aT ÷ (b + T);  T_d = b α ÷ (a − α)', 'T|air temperature|°C; RH|relative humidity|%; Td~T_d|dew point|°C', 'a = 17.625, b = 243.04 °C; about 0–60 °C. Educational estimate.', 'Td', v => { const a = 17.625, b = 243.04, al = Math.log(v.RH / 100) + a * v.T / (b + v.T); return b * al / (a - al); }, { T: 25, RH: 60 }, ['dew-point', 'wth-humid'], ['weather']);
