FORM('escape-velocity', 'Escape velocity', 'Physics', 'v = √(2 G M ÷ r)', 'G|gravitational constant|N·m²/kg²; M|mass of the body|kg; r|distance from centre|m; v|escape speed|m/s', 'No atmosphere.', 'v', v => Math.sqrt(2 * v.G * v.M / v.r), { G: 6.6743e-11, M: 5.972e24, r: 6.371e6 }, ['escape-v'], ['science', 'constants']);
FORM('conduction', 'Heat conduction through a wall', 'Physics', 'Q̇ = k A ΔT ÷ d', 'k|thermal conductivity|W/m·K; A|area|m²; dT~ΔT|temperature difference|K; d|thickness|m; Q|heat flow|W', 'Steady state, one-dimensional.', 'Q', v => v.k * v.A * v.dT / v.d, { k: 0.04, A: 10, dT: 20, d: 0.1 }, ['cp-conduction'], ['chem-phys']);
FORM('specific-heat', 'Sensible heat', 'Physics', 'Q = m c ΔT', 'm|mass|kg; c|specific heat|J/kg·K; dT~ΔT|temperature change|K; Q|heat|J', 'No phase change.', 'Q', v => v.m * v.c * v.dT, { m: 2, c: 4186, dT: 30 }, ['heat-q', 'cp-heat-phase', 'wt-heat'], ['chem-phys', 'water']);
FORM('stefan', 'Stefan–Boltzmann radiation', 'Physics', 'P = ε σ A T⁴', 'eps~ε|emissivity|; sigma~σ|Stefan–Boltzmann constant (5.670374 × 10⁻⁸)|W/m²·K⁴; A|area|m²; T|absolute temperature|K; P|radiated power|W', 'Net exchange needs the surroundings’ T⁴ subtracted.', 'P', v => v.eps * v.sigma * v.A * v.T ** 4, { eps: 0.9, sigma: 5.670374e-8, A: 1, T: 300 }, ['cp-radiation'], ['chem-phys']);
FORM('carnot', 'Carnot efficiency', 'Physics', 'η = 1 − T_c ÷ T_h', 'Tc~T_c|cold reservoir (absolute)|K; Th~T_h|hot reservoir (absolute)|K; eta~η|maximum efficiency|', 'Upper limit for any heat engine between two temperatures.', 'eta', v => 1 - v.Tc / v.Th, { Tc: 300, Th: 600 }, ['cp-carnot'], ['chem-phys']);
FORM('ideal-gas-v', 'Ideal gas law (volume)', 'Physics', 'V = n R T ÷ P', 'n|amount|mol; R|gas constant (8.314462)|J/mol·K; T|absolute temperature|K; P|absolute pressure|Pa; V|volume|m³', 'Low pressure, high temperature.', 'V', v => v.n * v.R * v.T / v.P, { n: 1, R: 8.314462618, T: 273.15, P: 101325 }, ['ideal-gas', 'gas-law', 'gas-density'], ['air-gases', 'chem-phys']);
FORM('wave-speed', 'Wave speed', 'Physics', 'v = f λ', 'f|frequency|Hz; lambda~λ|wavelength|m; v|wave speed|m/s', 'Sound in air ≈ 343 m/s at 20 °C.', 'v', v => v.f * v.lambda, { f: 440, lambda: 0.78 }, ['sci-wave', 'wavelength'], ['science']);
FORM('snell', 'Snell’s law', 'Physics', 'sin θ₂ = (n₁ ÷ n₂) sin θ₁', 'n1~n₁|refractive index of medium 1|; n2~n₂|refractive index of medium 2|; t1~θ₁|angle of incidence|°; t2~θ₂|angle of refraction|°', 'Total internal reflection if the sine exceeds 1.', 't2', v => Math.asin(v.n1 / v.n2 * Math.sin(v.t1 * D2)) / D2, { n1: 1, n2: 1.5, t1: 30 }, ['sci-snell'], ['science']);
FORM('thin-lens', 'Thin-lens equation (image distance)', 'Physics', '1 ÷ d_i = 1 ÷ f − 1 ÷ d_o', 'f|focal length|; do~d_o|object distance|; di~d_i|image distance|', 'Thin lens, paraxial rays; same length unit for all.', 'di', v => 1 / (1 / v.f - 1 / v.do), { f: 10, do: 30 }, ['sci-lens'], ['science']);
FORM('coulomb', 'Coulomb’s law', 'Physics', 'F = k q₁ q₂ ÷ r²', 'k|Coulomb constant (8.98755 × 10⁹)|N·m²/C²; q1~q₁|first charge|C; q2~q₂|second charge|C; r|separation|m; F|force|N', 'Point charges in vacuum.', 'F', v => v.k * v.q1 * v.q2 / (v.r * v.r), { k: 8.9875517923e9, q1: 1e-6, q2: 2e-6, r: 0.1 }, ['cp-coulomb'], ['chem-phys']);
// ---- Financial mathematics
FORM('simple-interest', 'Simple interest', 'Financial mathematics', 'I = P r t', 'P|principal|$; r|annual rate (decimal)|; t|time|years; I|interest|$', 'Interest not reinvested; rate and time in matching units (per year, years).', 'I', v => v.P * v.r * v.t, { P: 1000, r: 0.05, t: 3 }, ['mo-simple'], ['money']);
FORM('compound-fv', 'Compound interest (future value)', 'Financial mathematics', 'FV = P (1 + r ÷ n)^(n t)', 'P|principal|$; r|annual rate (decimal)|; n|compounding periods per year|; t|years|; FV|future value|$', 'Fixed rate, no deposits or withdrawals; interest compounds n times per year.', 'FV', v => v.P * Math.pow(1 + v.r / v.n, v.n * v.t), { P: 1000, r: 0.05, n: 12, t: 10 }, ['mo-comp', 'compound'], ['money']);
FORM('loan-payment', 'Loan payment', 'Financial mathematics', 'M = P r ÷ [1 − (1 + r)^(−n)]', 'P|loan amount|$; r|rate per period (decimal)|; n|number of payments|; M|payment per period|$', 'Fixed-rate fully amortizing loan, payment at period end.', 'M', v => v.P * v.r / (1 - Math.pow(1 + v.r, -v.n)), { P: 20000, r: 0.005, n: 60 }, ['loan', 'mo-loan', 'afford'], ['money']);
FORM('rule72', 'Rule of 72', 'Financial mathematics', 't ≈ 72 ÷ r%', 'r|annual rate|%; t|years to double|', 'Best for rates of about 6–10 %.', 't', v => 72 / v.r, { r: 6 }, ['rate72'], ['money']);
FORM('cagr', 'Compound annual growth rate', 'Financial mathematics', 'CAGR = (End ÷ Start)^(1 ÷ n) − 1', 'S~Start|beginning value|; E~End|ending value|; n|years|; CAGR|growth rate (fraction)|', 'Start and end values positive; ignores the path between them.', 'CAGR', v => Math.pow(v.E / v.S, 1 / v.n) - 1, { S: 1000, E: 1800, n: 5 }, ['mo-cagr'], ['money']);
FORM('present-value', 'Present value of a future sum', 'Financial mathematics', 'PV = FV ÷ (1 + r)ⁿ', 'FV|future value|$; r|rate per period (decimal)|; n|periods|; PV|present value|$', 'Single future amount at a constant discount rate per period.', 'PV', v => v.FV / Math.pow(1 + v.r, v.n), { FV: 10000, r: 0.04, n: 5 }, ['mo-tvm', 'mo-npv'], ['money']);
FORM('fisher', 'Real interest rate (Fisher)', 'Financial mathematics', 'r_real = (1 + r_nom) ÷ (1 + i) − 1', 'rn~r_nom|nominal rate (decimal)|; i|inflation (decimal)|; rr~r_real|real rate|', 'Rates as decimals; exact form of the Fisher relation.', 'rr', v => (1 + v.rn) / (1 + v.i) - 1, { rn: 0.05, i: 0.03 }, ['inflation'], ['money']);
FORM('ear', 'Effective annual rate', 'Financial mathematics', 'EAR = (1 + r ÷ n)ⁿ − 1', 'r|nominal annual rate (decimal)|; n|compounding periods per year|; EAR|effective rate|', 'Rate as a decimal; compares different compounding frequencies.', 'EAR', v => Math.pow(1 + v.r / v.n, v.n) - 1, { r: 0.06, n: 12 }, ['mo-ear'], ['money']);
FORM('markup-price', 'Selling price from markup', 'Financial mathematics', 'price = cost × (1 + markup)', 'cost|unit cost|$; mk~markup|markup (decimal)|; price|selling price|$', 'Markup is on cost; margin is on price.', 'price', v => v.cost * (1 + v.mk), { cost: 40, mk: 0.5 }, ['mo-markup'], ['money']);
FORM('margin', 'Gross margin', 'Financial mathematics', 'margin = (price − cost) ÷ price', 'price|selling price|$; cost|unit cost|$; margin|margin (fraction)|', 'Price above zero; margin is a fraction of price, not of cost.', 'margin', v => (v.price - v.cost) / v.price, { price: 60, cost: 40 }, ['margin', 'mo-markup'], ['money']);
FORM('depreciation', 'Straight-line depreciation', 'Financial mathematics', 'D = (cost − salvage) ÷ life', 'cost|purchase cost|$; salvage|residual value|$; life|useful life|years; D|annual depreciation|$', 'Straight-line method; salvage below cost and life above zero.', 'D', v => (v.cost - v.salvage) / v.life, { cost: 25000, salvage: 5000, life: 5 }, ['depreciation', 'mo-depr'], ['money']);
FORM('sale-price', 'Discounted price', 'Financial mathematics', 'sale = price × (1 − discount)', 'price|original price|$; d~discount|discount (decimal)|; sale|sale price|$', 'Discount as a decimal (0.25 = 25 %); applies to the original price.', 'sale', v => v.price * (1 - v.d), { price: 80, d: 0.25 }, ['mo-disc'], ['money']);
FORM('breakeven', 'Break-even quantity', 'Financial mathematics', 'Q = fixed ÷ (price − variable cost)', 'fixed|fixed costs|$; price|unit price|$; vc~variable cost|per unit|$; Q|units to break even|', 'Price must exceed variable cost.', 'Q', v => v.fixed / (v.price - v.vc), { fixed: 6000, price: 25, vc: 10 }, ['mo-pl'], ['money']);
FORM('annuity-fv', 'Future value of regular deposits', 'Financial mathematics', 'FV = PMT × [(1 + r)ⁿ − 1] ÷ r', 'PMT|deposit per period|$; r|rate per period (decimal)|; n|number of deposits|; FV|future value|$', 'Deposits at period end.', 'FV', v => v.PMT * (Math.pow(1 + v.r, v.n) - 1) / v.r, { PMT: 200, r: 0.004, n: 120 }, ['mo-tvm'], ['money']);
/* ===== Formula Encyclopedia chapter (static tables per discipline + dynamic browser) ===== */
const feKey = d => d.toLowerCase().replace(/[^a-z]+/g, '-').replace(/^-|-$/g, '');
const feRel = f => f.chs.filter(c => APP.byId[c]).slice(0, 2).map(c => `[[${c}|${APP.byId[c].title}]]`).join(', ');
const feTable = d => T(['Formula', 'Equation', 'Result unit', 'Related chapters'], REG.all('formula').filter(f => f.disc === d).sort((a, b) => a.name.localeCompare(b.name)).map(f => { const o = f.vars.find(v => v.k === f.out); return [f.name, f.eq, (o && o.u) || '—', feRel(f) || '—']; }), { cap: d + ' formulas (curated, with worked examples in the browser)', filter: true, idx: true });
CH('formulas', 'ref', 'Formula Encyclopedia', '∑',
  'A central database of formulas with variable definitions, units, conditions, a worked example computed live, related calculators and related chapters. Browse A–Z or by discipline, or search by name, symbol, equation or abbreviation. Formulas written inside the chapters are collected too. Related: <a href="#index">Index</a>, <a href="#conversions">Conversions</a>.',
  [
    S('fe-browse', 'Browse the formula encyclopedia', [DYN('formulas')], { kw: ['formulas', 'formula database', 'equations', 'formula list', 'formula encyclopedia', 'browse formulas', 'formula search', 'variables and units', 'worked example'], see: ['index|Index', 'conversions|Conversions'] }),
    S('fe-using', 'How to read a formula entry', [
      NOTE('Each entry gives the equation, what every symbol means, the units to use, and the conditions under which the formula is valid. Always check the conditions: a correct formula used outside its conditions gives a wrong answer.'),
      UL(['<b>Variables and units</b> are listed together; use the units shown or convert first (see [[conversions|Conversions]]).', '<b>Worked example</b> is computed by the same function the “Try your own values” boxes use, so the numbers always agree.', '<b>Related calculators</b> jump to the calculator inside its chapter.', '<b>Formulas from the chapters</b> (marked “chapter”) show the equation and note exactly as written in the chapter and link back to it.', 'Equations are written in plain text: × multiply, ÷ divide, ^ power, √ square root, subscripts as _x.']),
      P('Disciplines used for grouping: ' + DISC.join(', ') + '. Formulas that fit none of these are filed under “' + DISC_OTHER + '”.')
    ], { kw: ['how to read formula', 'formula conditions', 'formula units', 'variables'] }),
    ...DISC.map(d => S('fe-d-' + feKey(d), d + ' formulas', [NOTE('Curated ' + d.toLowerCase() + ' formulas. Open the browser above for variable definitions and a worked example for each.'), feTable(d)], { kw: [d + ' formulas', d + ' equations'] })),
    S('fe-registry', 'Reference data registry (how the data is organized)', [
      P('All reference data lives in structured JavaScript registries, so new material can be added without changing the application structure.'),
      DYN('datareg'),
      UL(['<b>REG.define(kind, validator)</b> creates a registry; <b>REG.add(kind, item)</b> validates and stores an item; <b>REG.all(kind)</b> lists them.', '<b>FORM(id, name, discipline, equation, variables, conditions, output, fn, example, calculators, chapters)</b> adds a curated formula. Its example is run when the data loads, so a broken formula stops the build instead of reaching users.', '<b>CH / S / T / FX / CALC / UC</b> add chapters, sections, tables, formulas, calculators and unit families in the same additive way.', 'Chapters, calculators and units are discovered automatically by the index, the encyclopedia and search.'])
    ], { kw: ['data registry', 'reference data', 'REG', 'data structure', 'architecture', 'extending the app'] })
  ]);
/* ===== Technical dictionary engine + calculator discipline map ===== */
REG.define('term', { validate(t) { if (!t.id || !t.term || !t.defs || !t.defs.length) throw new Error('term needs id, term and a definition: ' + t.id); if (DISC.indexOf(t.subject) < 0 && t.subject !== DISC_OTHER) throw new Error('bad subject for ' + t.term + ': ' + t.subject); } });
const termKey = s => String(s).toLowerCase().replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, ' ').replace(/\([^)]*\)/g, ' ').replace(/[^a-z0-9µ°²³ ]+/g, ' ').replace(/\s+/g, ' ').trim();
/* TERM(term, subject, definition, [abbreviations], [related terms], [chapter ids]) */
function TERM(term, subject, def, abbr, related, chs) { return REG.add('term', { id: 't:' + termKey(term), term, subject, defs: [{ def, subject, ch: '', sec: '' }], abbr: abbr || [], related: related || [], chs: chs || [], curated: true }); }
function harvestTerms() {
  const map = new Map();
  REG.all('term').forEach(t => map.set(t.id, { id: t.id, term: t.term, defs: t.defs.map(d => Object.assign({}, d)), abbr: t.abbr.slice(), related: t.related.slice(), chs: t.chs.slice(), curated: true, subjects: new Set([t.subject]) }));
  APP.chapters.forEach(c => c.sections.forEach(s => {
    const re = /<dt data-idx="[^"]*">([\s\S]*?)<\/dt><dd>([\s\S]*?)<\/dd>/g; let m;
    while ((m = re.exec(s.html))) {
      let raw = unesc(m[1].replace(/<[^>]+>/g, '')).trim(); if (!raw) continue;
      const abbr = []; const pm = raw.match(/\(([^)]{1,12})\)\s*$/); let term = raw;
      if (pm && !/\s{2}/.test(pm[1])) { abbr.push(pm[1].trim()); term = raw.replace(/\s*\([^)]*\)\s*$/, '').trim() || raw; }
      const key = 't:' + termKey(term); if (key === 't:') continue;
      let subj = CH_DISC[c.id] || DISC_OTHER; if (/^(chem-phys|science|water)$/.test(c.id) && /\b(mole|molar|molarity|molality|acid|alkal|base\b|ion\b|ions\b|ionic|atom|atomic|element|compound|molecule|reaction|oxid|reduc|catalyst|solution|solute|solvent|concentration|ph\b|titrat|hardness|salin|dissolved|isotope|electrolyte|stoich|valence|bond)/i.test(raw + ' ' + m[2].replace(/<[^>]+>/g, ''))) subj = 'Chemistry'; let e = map.get(key);
      if (!e) { e = { id: key, term, defs: [], abbr: [], related: [], chs: [], subjects: new Set() }; map.set(key, e); }
      if (!e.defs.some(d => d.ch === c.id && d.sec === s.id)) e.defs.push({ def: m[2], subject: subj, ch: c.id, sec: s.id });
      abbr.forEach(a => { if (!e.abbr.includes(a)) e.abbr.push(a); }); if (!e.chs.includes(c.id)) e.chs.push(c.id); e.subjects.add(subj);
    }
  }));
  return [...map.values()];
}
