          function () { var kwh = 1.5 * 3; return { title: 'Heater energy', given: ['A 1,500 W heater runs 3 h.'], steps: ['Energy = 1.5 kW × 3 h = ' + f(kwh, 1) + ' kWh = ' + f(kwh * 3.6, 1) + ' MJ.', 'At $0.15/kWh the cost = $' + f(kwh * 0.15, 2) + ' (assumed price).'], result: f(kwh, 1) + ' kWh = ' + f(kwh * 3.6, 1) + ' MJ.' }; },
