          function () { var b = '101101111010', g = b.match(/.{4}/g), h = g.map(function (x) { return hex(parseInt(x, 2)); }).join(''); return { title: 'Binary to hex by grouping', given: ['101101111010.'], steps: ['Groups of four: ' + g.join(' ') + '.', 'Each group: ' + g.map(function (x) { return x + '→' + hex(parseInt(x, 2)); }).join(', ') + '.'], result: '0x' + h + ' = ' + f(parseInt(h, 16), 0) + ' in decimal.' }; },
          function () { var n = 0x1F4A, parts = [[1, 4096], [15, 256], [4, 16], [10, 1]]; return { title: 'Hex to decimal (the chapter’s 0x1F4A)', given: ['0x1F4A.'], steps: parts.map(function (p) { return p[0] + ' × ' + p[1] + ' = ' + f(p[0] * p[1], 0); }).concat(['Sum = ' + f(n, 0) + '.']), result: '0x1F4A = ' + f(n, 0) + '.' }; },
