          function () { var rows = [['Dial-up 56 kbit/s', 56e3], ['Fast Ethernet 100 Mbit/s', 100e6], ['Gigabit Ethernet', 1e9], ['USB 3.0 5 Gbit/s', 5e9], ['USB4 40 Gbit/s', 40e9]].map(function (r) { return r[0] + ': ' + dur(8e9 / r[1] > 0 ? 1e9 * 8 / r[1] : 0); }); return { title: 'Moving 1 GB at ideal speed', given: ['No protocol overhead.'], steps: rows, result: 'Dial-up needs 1 d 15 h 40 min 57 s for 1 GB, matching the chapter’s table; USB4 needs 0.2 s.' }; },
