          function () { var rows = [['A', 'U+0041'], ['é', 'U+00E9'], ['€', 'U+20AC'], ['😀', 'U+1F600']].map(function (r) { var e = enc(r[0]); return r[0] + ' (' + r[1] + '): ' + e + ' = ' + e.split(' ').length + ' byte(s)'; }); return { title: 'UTF-8 byte lengths', given: ['Four characters.'], steps: rows, result: 'ASCII stays one byte; other scripts take two or three; emoji take four.' }; },
