  var vitals = { adult: { rr: [12, 20], hr: [60, 100], sbp: [90, 120] }, child: { rr: [18, 30], hr: [70, 120], sbp: [80, 110] }, infant: { rr: [30, 60], hr: [100, 160], sbp: [70, 95] } };
