          function () { var ft = 12, w = 15, a = ft * w, m2 = a * A.ft2, sq = Math.pow(0.3048, 2); return { title: 'Area conversion squares the factor', given: ['A room 12 ft × 15 ft.'], steps: ['Area = ' + a + ' ft².', '1 ft² = 0.3048² = ' + sg(sq, 8) + ' m².', 'Area = ' + a + ' × ' + sg(sq, 8) + ' = ' + sg(m2, 5) + ' m².', 'Check by sides: ' + sg(ft * 0.3048, 5) + ' m × ' + sg(w * 0.3048, 5) + ' m = ' + sg(ft * 0.3048 * w * 0.3048, 5) + ' m².'], result: a + ' ft² = ' + sg(m2, 4) + ' m².' }; },
