          function () { var g = 1000, r = cv(g, Q, 'gpm', 'm3h'), D = 6, area = Math.PI * Math.pow(D / 12 / 2, 2), v = (g / 448.8312) / area; return { title: 'Flow and pipe velocity (6 in pipe, illustrative)', given: ['1,000 gpm; 1 ft³/s = 448.83 gpm.'], steps: ['In m³/h: ' + sg(r, 6) + '.', 'Pipe area = ' + f(area, 4) + ' ft².', 'Velocity = (1,000 ÷ 448.83) ÷ ' + f(area, 4) + ' = ' + f(v, 1) + ' ft/s.', 'Check: 2.448 × 6² × ' + f(v, 1) + ' = ' + f(2.448 * 36 * v, 0) + ' gpm.'], result: '1000 gpm = ' + sg(r, 5) + ' m³/h; in a 6 in pipe that is about ' + f(v, 0) + ' ft/s.' }; },
