          function () { var rowsA = [['1 rad', 1 * 180 / Math.PI], ['90°', 90 * Math.PI / 180], ['6400 mil', 360], ['1 grad', 0.9]].map(function (r) { return r[0] + ' = ' + sg(r[1], 7); }); return { title: 'Angle', given: ['rad = deg × π/180; 6,400 NATO mils = 360°.'], steps: ['1 rad = ' + sg(180 / Math.PI, 7) + '°.', '90° = ' + sg(Math.PI / 2, 7) + ' rad.', '1 NATO mil = ' + sg(0.05625, 5) + '°.', '1 arcminute = ' + sg(1 / 60, 6) + '°.'], result: 'A full circle: 2π rad = 360° = 400 grad = 6,400 mil.' }; },
