          function () { var y = 2026, d0 = doomYear(y), dd = doomDates(y), rows = dd.map(function (d, i) { var w = jsDow(y, i + 1, d); return (i + 1) + '/' + d + '/' + y + ' → ' + DN[w].slice(0, 3) + (w === d0 ? ' ✓' : ' ✗'); }); return { title: 'Every doomsday date in 2026', given: ['The twelve anchor dates.'], steps: rows, result: 'All twelve fall on ' + DN[d0] + ': the browser confirms each one.' }; },
          function () { var y = 2026, m = 11, d = 17, dd = doomYear(y), anchor = doomDates(y)[m - 1], diff = d - anchor, w = ((dd + diff) % 7 + 7) % 7; return { title: 'Weekday of 17 November 2026 by Doomsday', given: ['Doomsday 2026 is ' + DN[dd] + '; the November anchor is 11/7.'], steps: ['17 − 7 = ' + diff + ' days after the doomsday.', '(' + dd + ' + ' + diff + ') mod 7 = ' + w + ' = ' + DN[w] + '.'], result: DN[w] + ', the same answer as the Sakamoto algorithm.' }; },
