  var typeCount = function (ix) { var t = {}; ix.forEach(function (e) { e.types.forEach(function (x) { t[x] = (t[x] || 0) + 1; }); }); return t; };
  var letterCount = function (ix) { var c = {}; ix.forEach(function (e) { var L = letter(e.term); c[L] = (c[L] || 0) + 1; }); return c; };
  var ORDER = ['Chapter', 'Section', 'Calculator', 'Formula', 'Table', 'Definition', 'Unit', 'Topic', 'Heading'];
