      { q: 'Find the monthly payment on 15,000 at 0.4 % per month over 48 months (illustration only).', a: function () { return sg(15000 * 0.004 / (1 - Math.pow(1.004, -48)), 6) + ' per month.'; } },
      { q: 'Solve V = I R for R, then find R when V = 24 V and I = 0.5 A.', a: function () { return 'R = V ÷ I = ' + sg(24 / 0.5) + ' Ω.'; } },
      { q: 'If radiated power goes as T⁴, by what percentage does it change when the kelvin temperature rises 5 %?', a: function () { return f((Math.pow(1.05, 4) - 1) * 100, 1) + ' % increase.'; } }
