          function () { if (!OK()) return NA; var found = null; ids().forEach(function (id) { if (found) return; APP.calcs[id].fields.forEach(function (f) { if (found || !f.s) return; if (f.s.every(function (o) { return /^-?\d+(\.\d+)?$/.test(String(o[0])); })) found = { id: id, f: f }; }); }); if (!found) return { title: 'Numeric choice codes', given: ['Look for a list whose codes are all numbers.'], steps: ['No such list was found in this version.'], result: 'Nothing to show.' }; var v = VALS(APP.calcs[found.id]), t = typeof v[found.f.k]; var textual = null; ids().forEach(function (id) { if (textual) return; APP.calcs[id].fields.forEach(function (f) { if (textual || !f.s || f.s.some(function (o) { return /^-?\d+(\.\d+)?$/.test(String(o[0])); })) return; textual = { id: id, f: f }; }); }); var t2 = textual ? typeof VALS(APP.calcs[textual.id])[textual.f.k] : 'string'; return { title: 'Choice codes become numbers or stay text', given: ['One list with numeric codes and one with text codes.'], steps: [found.id + ' / ' + found.f.l + ': default code type is ' + t + ' ' + tf(t === 'number') + '.', (textual ? textual.id + ' / ' + textual.f.l : 'a text list') + ': default code type is ' + t2 + ' ' + tf(t2 === 'string') + '.'], result: t === 'number' && t2 === 'string' ? 'Numeric-looking codes are numbers; other codes stay text.' : 'MISMATCH: a code type differs from the description.' }; },
