  const res = search(q, 60), tk = tokens(q), qc = quickConvert(q);
  m.innerHTML = `<div class="crumb">Search</div><h1>Results for “${esc(q)}”</h1>${qc ? qcHTML(qc) : ''}<p class="lead">${res.length} result${res.length === 1 ? '' : 's'}</p><div class="rl">${res.map(d => resultHTML(d, tk)).join('')}</div>`;
