DYNS.formulas = el => mountFormulas(el);
DYNS.datareg = el => { el.innerHTML = `<div class="tw"><table><caption>Registries loaded in this app</caption><thead><tr><th>Registry</th><th>Entries</th></tr></thead><tbody>${[...REG.stats(), ['chapters', APP.chapters.length], ['sections', APP.chapters.reduce((a, c) => a + c.sections.length, 0)], ['calculators', Object.keys(APP.calcs).length], ['unit families', Object.keys(APP.units).length]].map(r => `<tr><td>${esc(r[0])}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table></div>`; };

/* ---------- phase 2: calculator center, dictionary, master search (additive) ---------- */
