document.addEventListener('click', e => { const a = e.target.closest && e.target.closest('[data-goto]'); if (a) { const p = a.dataset.goto.split(':'); GOTO[p[0]] = p.slice(1).join(':'); } });
const chDisc = ch => CH_DISC[ch] || DISC_OTHER;
/* --- calculator center --- */
