    const sh = t.length <= 3, f = (txt) => txt && (sh ? msWord(txt, t) : msPrefix(txt, t)); let s = 0;
    if (f(d.lt)) s += 12 + (d.lt.startsWith(t) || d.lt.includes(' ' + t) ? 5 : 0);
    if (d.ab && f(d.ab)) s += 14; if (f(d.lk)) s += 7; if (f(d.sub.toLowerCase())) s += 2;
    if (f(d.lx)) { s += 1; if (!sh) { let n = 0, p = d.lx.indexOf(t); while (p >= 0 && n < 6) { n++; p = d.lx.indexOf(t, p + t.length); } s += n * .5; } }
