    $$('.mst button', el).forEach(b => { const t = b.dataset.t; b.classList.toggle('pri', t === type); b.querySelector('i').textContent = t === 'All' ? (q ? Object.values(msSearch(q, 'All', disc).counts).reduce((a, b2) => a + b2, 0) : '') : (q ? (msSearch(q, 'All', disc).counts[t] || 0) : ''); });
