    bookmarks(f) { const items = st.bm.map(k => ({ k, b: nbBmItem(k) })).filter(x => x.b && match(x, f)); return items.map(({ k, b }) => `<div class="nb-i"><a class="r" href="${b.href}"${b.goto ? ` data-goto="${esc(b.goto)}"` : ''}><b><span class="tag">${b.tag}</span>${esc(b.title)}</b><small>${esc(b.sub)}</small></a><button class="btn" data-nb="unbm" data-key="${esc(k)}">Remove bookmark</button></div>`).join('') || '<p class="nb-empty">No bookmarks yet. Tap ☆ beside any section, calculator, formula or dictionary term.</p>'; },
    formulas(f) { return st.nb.formulas.filter(x => match(x, f)).map(n => `<div class="nb-i" data-k="formulas" data-id="${esc(n.id)}"><b>${esc(n.name)}</b> <a href="#formulas--fe-browse" data-goto="fe:${esc(n.fid)}">open in encyclopedia</a><div class="fx"><code>${esc(n.eq)}</code></div>${Object.keys(n.vals).length ? `<p>Values: ${Object.keys(n.vals).map(k => esc(k) + ' = ' + esc(fwNum(n.vals[k]))).join(', ')}${n.result ? ' → <b>' + esc(n.result) + '</b>' : ''}</p>` : ''}<textarea class="nb-ed" data-f="note" rows="2" placeholder="Your note…" aria-label="Note">${esc(n.note)}</textarea>${when(n)} ${del(n.id)}</div>`).join('') || '<p class="nb-empty">No saved formulas. Open a formula in the <a href="#formulas--fe-browse">Formula Encyclopedia</a> and press “Save to notebook”.</p>'; },
    results(f) { return st.nb.results.filter(x => match(x, f)).map(n => `<div class="nb-i" data-k="results" data-id="${esc(n.id)}"><b>${esc(n.title)}</b> ${APP.calcs[n.calc] ? `<a href="#${APP.calcHome[n.calc].ch}--${APP.calcHome[n.calc].sec}" data-goto="cc:${esc(n.calc)}">open calculator</a>` : '<small>(calculator no longer available)</small>'}<pre class="nb-pre">${esc(n.text)}</pre><textarea class="nb-ed" data-f="note" rows="2" placeholder="Your note…" aria-label="Note">${esc(n.note)}</textarea>${when(n)} <button class="btn" data-nb="copy" data-id="${esc(n.id)}">Copy</button> ${APP.calcs[n.calc] ? `<button class="btn" data-nb="restore" data-id="${esc(n.id)}">Restore inputs</button>` : ''} ${del(n.id)}</div>`).join('') || '<p class="nb-empty">No saved results. Press “Save result” under any calculator.</p>'; },
    entries(f) { const dopt = sel => DISC.concat([DISC_OTHER]).map(d => `<option${d === sel ? ' selected' : ''}>${esc(d)}</option>`).join(''); return `<div class="nb-new"><input class="nb-t" placeholder="Title (required)" aria-label="Entry title"><select class="nb-d" aria-label="Discipline">${dopt(DISC_OTHER)}</select><input class="nb-a" placeholder="Abbreviation" aria-label="Abbreviation"><input class="nb-e" placeholder="Equation (optional)" aria-label="Equation"><textarea class="nb-b" rows="4" placeholder="Definition or content…" aria-label="Content"></textarea><button class="btn pri" data-nb="add-entry">Add entry</button></div>` + (st.nb.entries.filter(x => match(x, f)).map(n => `<div class="nb-i" data-k="entries" data-id="${esc(n.id)}"><input class="nb-ed" data-f="title" value="${esc(n.title)}" aria-label="Title"><select class="nb-ed" data-f="disc" aria-label="Discipline">${dopt(n.disc)}</select><input class="nb-ed" data-f="abbr" value="${esc(n.abbr)}" placeholder="abbreviation" aria-label="Abbreviation"><input class="nb-ed" data-f="eq" value="${esc(n.eq)}" placeholder="equation" aria-label="Equation"><textarea class="nb-ed" data-f="body" rows="4" aria-label="Content">${esc(n.body)}</textarea>${when(n)} ${del(n.id)}</div>`).join('') || '<p class="nb-empty">No custom entries yet. They are searchable in the Master Reference Search.</p>'); },
    backup() { const c = { n: st.nb.notes.length, e: st.nb.entries.length, f: st.nb.formulas.length, r: st.nb.results.length, b: st.bm.length, s: Object.keys(st.notes).filter(k => st.notes[k]).length }; return `<h4>Export</h4><p>Exports ${c.n} notes, ${c.e} custom entries, ${c.f} saved formulas, ${c.r} saved results, ${c.b} bookmarks and ${c.s} section notes as one JSON file.</p><p><button class="btn pri" data-nb="dl">Download JSON file</button> <button class="btn" data-nb="copyjson">Copy JSON</button> <button class="btn" data-nb="showjson">Show JSON text</button></p><textarea class="nb-json" readonly rows="6" hidden aria-label="Exported JSON"></textarea><h4>Import</h4><p><input type="file" class="nb-file" accept=".json,application/json" aria-label="Choose an exported JSON file"></p><p>…or paste exported JSON here:</p><textarea class="nb-paste" rows="5" placeholder="Paste exported JSON" aria-label="Paste exported JSON"></textarea><p><button class="btn" data-nb="check">Check</button></p><div class="nb-prev" aria-live="polite"></div><p><label><input type="radio" name="nbm" value="merge" checked> Merge with my notebook (keeps newer items)</label><br><label><input type="radio" name="nbm" value="replace"> Replace my notebook with the file</label></p><p><button class="btn pri nb-imp" data-nb="import" disabled>Import</button></p>`; }
