  const render = () => {
    const f = ($('.nbf', el) ? $('.nbf', el).value : '').trim().toLowerCase();
    el.innerHTML = `<div class="nb"><div class="nb-tabs">${tabs.map(([k, l]) => `<button class="btn ${k === tab ? 'pri' : ''}" data-tab="${k}">${l}${count(k) !== '' ? ' <i>' + count(k) + '</i>' : ''}</button>`).join('')}</div>${tab === 'backup' ? '' : `<input class="tfilter nbf" type="search" placeholder="Filter this list…" aria-label="Filter" value="${esc(f)}">`}<div class="nb-body">${views[tab](f)}</div></div>`;
    pending = null;
  };
  const rerenderKeep = () => { const y = window.scrollY; render(); window.scrollTo(0, y); };
  const showPrev = text => { const r = nbParse(text), box = $('.nb-prev', el), btn = $('.nb-imp', el); pending = r.ok ? r : null; btn.disabled = !r.ok; btn.textContent = 'Import'; btn.dataset.armed = ''; if (!r.ok) { box.innerHTML = `<div class="err">${esc(r.error)}</div>`; return; } const c = r.counts; box.innerHTML = `<div class="hint">File contains ${c.notes} notes, ${c.entries} custom entries, ${c.formulas} saved formulas, ${c.results} saved results, ${c.bookmarks} bookmarks and ${c.sectionNotes} section notes${r.exported ? ' (exported ' + esc(r.exported) + ')' : ''}.${r.warnings.length ? '<br>' + r.warnings.map(esc).join('<br>') : ''}</div>`; };
