  if (t.id === 'bkd' || t.id === 'modal') { closeModal(); return; }
  if (t.id === 'bkr') { try { const o = JSON.parse($('#bk').value); KEYS.forEach(k => { if (k in o) { st[k] = o[k]; save(k); } }); applyTheme(); buildSide(); toast('Restored'); route(); closeModal(); } catch (er) { toast('Backup text is not valid'); } return; }
