$('#q').addEventListener('input', liveSearch);
$('#q').addEventListener('focus', liveSearch);
$('#q').addEventListener('keydown', e => { if (e.key === 'Enter' && $('#q').value.trim()) { lastQuery = $('#q').value; $('#sres').style.display = 'none'; if (location.hash === '#search') route(); else location.hash = '#search'; } if (e.key === 'Escape') { $('#sres').style.display = 'none'; e.target.blur(); } });
