/* ---------- additive extensions (constants library) ---------- */
if (typeof DYN_EXT !== 'undefined') { Object.assign(DYNS, DYN_EXT); if (typeof DYN_INIT === 'function') DYN_INIT(); }
/* ---------- boot ---------- */
applyTheme(); buildSide(); route();
/* ===== CATEGORY TEXTBOOKS: generation, views, quizzes, print-to-PDF (additive) ===== */
function tbRng(seed) { var h = 2166136261; for (var i = 0; i < seed.length; i++) { h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619); } return function () { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; return ((h >>> 0) % 100000) / 100000; }; }
