function tbPrint() {
  var t = document.title, art = $('.tb'); if (!art) return;
  document.title = 'Pocket Technical Reference — ' + (art.dataset.title || (tbCat(art.dataset.cat).title + ' (Category Textbook)'));
  try { window.print(); } catch (e) { toast('Printing is not available here. Open the file in a browser and try again.'); }
  setTimeout(function () { document.title = t; }, 500);
}
window.addEventListener('beforeprint', function () { document.querySelectorAll('.tb-keyd').forEach(function (d) { d.dataset.wasOpen = d.open ? '1' : ''; d.open = true; }); });
window.addEventListener('afterprint', function () { document.querySelectorAll('.tb-keyd').forEach(function (d) { d.open = !!d.dataset.wasOpen; }); });
document.addEventListener('click', function (e) {
  var a = e.target.closest && e.target.closest('a.tb-a');
  if (a) { e.preventDefault(); var t = document.getElementById(a.getAttribute('href').slice(1)); if (t) t.scrollIntoView({ block: 'start' }); return; }
  var b = e.target.closest && e.target.closest('[data-tb]'); if (!b) return;
  var act = b.dataset.tb;
  if (act === 'pdf') { tbPrint(); return; }
  var box = b.closest('.tb-quiz'); if (!box) return;
  if (act === 'clear') { box.querySelectorAll('input').forEach(function (i) { i.checked = false; }); box.querySelectorAll('.tb-q').forEach(function (q) { q.classList.remove('ok', 'bad'); q.querySelector('.tb-fb').textContent = ''; }); box.querySelector('.tb-score').textContent = ''; return; }
  if (act === 'check') {
    var qs = [].slice.call(box.querySelectorAll('.tb-q')), right = 0, answered = 0;
    qs.forEach(function (q) {
      var sel = q.querySelector('input:checked'), ans = +q.dataset.ans; q.classList.remove('ok', 'bad');
      var fb = q.querySelector('.tb-fb');
      if (!sel) { fb.textContent = 'Not answered. Correct answer: ' + TB_L[ans] + '.'; q.classList.add('bad'); return; }
      answered++; if (+sel.value === ans) { right++; q.classList.add('ok'); fb.textContent = 'Correct.'; } else { q.classList.add('bad'); fb.textContent = 'Not quite. Correct answer: ' + TB_L[ans] + '.'; }
    });
    var key = box.dataset.qz; if (!st.tb) st.tb = {}; var prev = st.tb[key];
    if (!prev || right > prev.best) { st.tb[key] = { best: right, of: qs.length }; save('tb'); }
    box.querySelector('.tb-score').textContent = 'Score: ' + right + ' / ' + qs.length + ' (best ' + st.tb[key].best + ')';
  }
});
if (KEYS.indexOf('tb') < 0) KEYS.push('tb');
/* ===== home page: numbered chapters, detailed descriptions and section links (additive) ===== */
function hcSnippet(s) {
  var h = s.html.replace(/<div class="slot[^>]*><\/div>/g, '');
  var m = h.match(/<(p|li|dd)[^>]*>([\s\S]*?)<\/\1>/);
  var t = m ? tbTxt(m[2]) : '';
  if (t.length < 25) { var c = h.match(/<caption>([\s\S]*?)<\/caption>/); if (c) t = 'Table: ' + tbTxt(c[1]); }
  if (t.length < 12) { var k = (s.html.match(/data-calc="([^"]+)"/) || [])[1]; if (k && APP.calcs[k]) t = 'Calculator: ' + APP.calcs[k].title; }
  if (t.length > 150) t = t.slice(0, 147).replace(/\s+\S*$/, '') + '…';
  return t;
}
function hcStats(ch) {
  var h = ch.sections.map(function (s) { return s.html; }).join('');
  var calcs = Object.keys(APP.calcHome).filter(function (id) { return APP.calcHome[id].ch === ch.id; }).length;
  return { sec: ch.sections.length, calcs: calcs, tables: (h.match(/<table/g) || []).length, figs: (h.match(/<svg/g) || []).length, words: Math.round(tbTxt(h).split(/\s+/).length / 100) * 100 };
}
function hcDesc(ch) {
  var st = hcStats(ch), parts = [];
  parts.push(st.sec + ' sections');
  if (st.tables) parts.push(st.tables + ' tables');
  if (st.calcs) parts.push(st.calcs + ' calculators');
  if (st.figs) parts.push(st.figs + ' figures');
  var cal = Object.keys(APP.calcHome).filter(function (id) { return APP.calcHome[id].ch === ch.id; }).slice(0, 4).map(function (id) { return APP.calcs[id].title; });
  return '<p class="hc-d">' + xr(ch.intro) + '</p><p class="hc-m">Contents: ' + parts.join(' · ') + (st.words ? ' · about ' + st.words.toLocaleString() + ' words' : '') + '.' + (cal.length ? ' Calculators include ' + cal.map(esc).join('; ') + (st.calcs > 4 ? ' and more' : '') + '.' : '') + '</p>';
}
function homeContents() {
  var h = '<h2 class="hc-h" id="contents">Full contents</h2><p class="lead">Every category, chapter and section. Click any chapter or section number to go straight to it.</p><div class="hc-jump">' + APP.cats.map(function (c, i) { return '<a href="#hc-' + c.id + '" class="hc-j">' + (i + 1) + '. ' + esc(c.title) + '</a>'; }).join('') + '</div>';
  APP.cats.forEach(function (c, i) {
    h += '<details class="hc-cat" id="hc-' + c.id + '"><summary><h3>' + c.icon + ' ' + (i + 1) + '. ' + esc(c.title) + ' <a class="hc-tb" href="#textbook-' + c.id + '">📖 Category Textbook</a></h3><p class="hc-bl">' + esc(c.blurb) + '</p></summary>';
    c.chapters.forEach(function (ch, j) {
      h += '<div class="hc-ch"><h4><a href="#' + ch.id + '"><span class="hc-n">' + (i + 1) + '.' + (j + 1) + '</span> ' + ch.icon + ' ' + esc(ch.title) + '</a></h4>' + (tbkHas(ch.id) ? '<p class="hc-bk">' + tbkLink(ch) + '</p>' : '') + hcDesc(ch) + '<details><summary>Sections (' + ch.sections.length + ')</summary><ol class="hc-secs">' + ch.sections.map(function (s, k) { var sn = hcSnippet(s); return '<li><a href="#' + ch.id + '--' + s.id + '"><span class="hc-n">' + (i + 1) + '.' + (j + 1) + '.' + (k + 1) + '</span> ' + esc(s.title) + '</a>' + (sn ? '<small>' + esc(sn) + '</small>' : '') + '</li>'; }).join('') + '</ol></details></div>';
    });
    h += '</details>';
  });
  return h;
}
